INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2095, '4121.010.32.1.075', '4121.010.26.1.075', 'Prestación de servicios de apoyo a la gestión', 'TÉCNICO', 'Prestación de servicios de apoyo a la gestión en la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico específicamente en  lo relacionado con la alimentación del Sistema de Información de Procesos Judiciales del Distrito.', '', 'CERRADO', 'ENERO-JUNIO', NULL, NULL, '2026-04-30', '2026-01-09', '2026-01-13', '2026-01-13', 'Treinta (30) de abril del dos mil veintiseis (2026)', 4, 30, 'Catorce millones doscientos cuatro mil pesos m/cte', 14204000.00, NULL, NULL, 'Tres millones quinientos cincuenta y un mil pesos m/cte', 3551000.00, 'Cuatro', 4, '', NULL, '1.Apoyar en la digitación y creación en el aplicativo del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, de las acciones constitucionales que le fueran notificadas al organismo. 2. Apoyar en la digitalización, cargue y actualización en el sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, los documentos inherentes a las actuaciones  constitucionales que le fueran notificadas al organismo. 3. Apoyar en la asignación de acciones constitucionales dentro del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública. 4. Apoyar cuando se le requiera, en las actividades de depuración de acciones de tutelas dentro del aplicativo de sistemas de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública.  5. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2211, 318, 31, 2603, 347, '', NULL, NULL, '', '', '', NULL, '', NULL, 'SI', 2, 'Siete millones ciento dos mil pesos M/cte', 7102000, 'Veintiún millones trescientos seis mil pesos M/cte', 21306000, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.9437169&isFromPublicArea=True&isModal=False', 'NO', 2026, '', NULL, 'NO');
INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2096, '4121.010.32.1.076', '4121.010.26.1.076', 'Prestación de servicios profesionales', 'PROFESIONAL', 'Prestación de servicios profesionales como Abogado, brindando soporte en el Departamento Administrativo de Gestión Jurídica Pública especificamente en la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico en las actividades correspondientes a la revisión y trámite de pago de sentencias, laudos arbitrales, conciliaciones, costas y demás,  que deba realizar el Distrito Especial de Santiago de Cali, en el marco del proyecto de inversión denominado "Fortalecimiento del Ciclo de Defensa Jurídica y de la Política de Mejora Normativa del Distrito Especial de Santiago de Cali BP-26005460"', '', 'CERRADO', 'ENERO-JUNIO', NULL, NULL, '2026-04-30', '2026-01-20', '2026-01-21', '2026-01-21', 'Treinta (30) de abril del dos mil veintiseis (2026)', 4, 30, 'Diecinueve millones doscientos veinte mil pesos m/cte', 19220000.00, NULL, NULL, 'Cuatro millones ochocientos cinco mil pesos m/cte', 4805000.00, 'Cuatro', 4, '', NULL, '1.Brindar apoyo al Departamento Administrativo de Gestión Jurídica Pública en la revisión de los documentos allegados por los solicitantes necesarios para el trámite de pago de sentencias, laudos arbitrales, conciliaciones y costas que deba realizar el Distrito  Especial de Santiago de Cali, de conformidad con las competencias señaladas dentro de los procedimientos establecidos por la entidad y realizar los requerimientos a los solicitantes, cuando sea necesario, así como elaboración de los oficios correspondientes para que se efectué el pago .  2. Brindar apoyo al Departamento Administrativo de Gestión Jurídica Pública en la elaboración o revisión de los documentos necesarios para el  trámite del pago de sentencias, laudos arbitrales, conciliaciones y costas a favor o en contra del Distrito Especial de Santiago de Cali., que se deban realizar de oficio conforme a lo establecido en las normas legales vigentes. 3. Brindar apoyo en la elaboración y diligenciamiento  del informe  en formato excel en el que se consigne mensualmente la información sobre los trámites de pagos de sentencias, laudos arbitrales, conciliaciones y costas judiciales que haya adelantado, conforme a las funciones y competencias del Departamento Administrativo de Gestión Jurídica Pública.  4. Proyectar los oficios que el Departamento Administrativo de Gestión Jurídica Pública mensualmente envie a la Secretaría de Educación, el Departamento Administrativo de Desarrollo e Innovación Institucional y el Departamento Administrativo de Hacienda con relación a los pagos de sentencias, laudos y conciliaciones a cargo del Distrito Especial de Santiago de Cali.  5. Las demás actividades que le asigne el supervisor del contrato y que se encuentren relacionadas con el objeto del mismo.', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2239, 318, 31, 2604, 347, '', NULL, NULL, '', '', '', NULL, '', NULL, 'SI', 2, 'Nueve millones seiscientos diez mil pesos M/cte', 9610000, 'Veintiocho millones ochocientos treinta mil pesos M/cte', 28830000, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.9626602&isFromPublicArea=True&isModal=False', 'NO', 2026, '', NULL, 'NO');
INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2097, '4121.010.32.1.077', '4121.010.26.1.077', 'Prestación de servicios de apoyo a la gestión', 'TÉCNICO', 'Prestación de servicios de apoyo a la gestión, brindando apoyo a las actividades que deba realizar el Departamento Administrativo de Gestión Jurídica Pública con relación al contigente judicial', '', 'CERRADO', 'ENERO-JUNIO', NULL, NULL, '2026-04-30', '2026-01-23', '2026-01-26', '2026-01-26', 'Treinta (30) de abril del dos mil veintiseis (2026)', 4, 30, 'Doce millones cuatrocientos veintiocho mil quinientos pesos m/cte', 12428500.00, NULL, NULL, 'Cuatro (4) cuotas, una (1) cuota de Un millón setecientos setenta y cinco mil pesos M/cte y tres (3) cuotas Tres millones quinientos cincuenta y un mil pesos m/cte', 3551000.00, 'Cuatro', 4, 'Un millón setecientos setenta y cinco mil  quinientos pesos M/cte', 1775500.00, '1. Apoyar a la elaboracion de informe mensual a la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico, las inconsistencias encontradas en conciliaciones prejudiciales, procesos judiciales y tramites arbitrales, relacionadas con el contingente judicial en el sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, para determinar su ajuste conjuntamente con el apoderado. 2) Apoyo  para la elaboracion del informe que consolide la información mensual relacionada con la valoración del contingente, de las conciliaciones prejudiciales, los procesos judiciales y laudos arbitrales registrados en el Sistema de Información de Procesos Judiciales del Departamento Administrativo de Gestión Jurídica Pública, que documente las cantidades de procesos calificados y pendientes por calificar. 3. Elaborar comunicaciones oficiales, actas y demás documentos que solicite el (la) Subdirector(a) de Defensa Judicial y Prevención del Daño Antijurídico. 4. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2217, 318, 31, 2605, 347, '', NULL, NULL, '', '', '', NULL, '', NULL, 'SI', 2, 'Seis millones ciento cincuenta y cinco mil sesenta y siete pesos M/cte', 7102000, 'Diecinueve millones quinientos treinta mil quinientos pesos M/cte', 19530500, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.9731635&isFromPublicArea=True&isModal=False', 'NO', 2026, '', NULL, 'NO');
INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2098, '4121.010.32.1.078', '4121.010.26.1.078', 'Prestación de servicios profesionales', 'ASESOR', 'Prestar servicios profesionales de asesoría jurídica especializada al Departamento Administrativo de Gestión Jurídica Pública de la Alcaldía Distrital de Santiago de Cali, en apoyo a sus funciones de orientación jurídica, defensa judicial, prevención del daño antijurídico y emisión de conceptos en materias administrativas, contractuales y demás relacionados con los proyectos de inversión financiados con los recursos provenientes de empréstito suscritos por el Distrito”.', '', 'CERRADO', 'ENERO-JUNIO', NULL, NULL, '2026-06-30', '2026-01-20', '2026-01-20', '2026-01-20', 'Treinta (30) de junio del dos mil veintiseis (2026)', 6, 30, 'Setenta y cuatro millones doscientos ocho mil pesos m/cte', 74208000.00, 62359664.00, 11848336.00, 'Doce millones trescientos sesenta y ocho mil M/cte', 12368000.00, 'Seis', 6, '', NULL, '', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2207, 318, 31, 2606, 348, '', NULL, NULL, 'Sesenta y dos millones trescientos cincuenta y nueve mil seiscientos sesenta y cuatro pesos M/cte', 'Once millones ochocientos cuarenta y ocho mil trescientos treinta y seis pesos M/cte', '', 10393277, '', 1974723, 'NO', 0, '', NULL, '', NULL, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.9627799&isFromPublicArea=True&isModal=False', 'SI', 2026, '', NULL, 'NO');
INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2099, '4121.010.32.1.079', '4121.010.26.1.079', 'Prestación de servicios profesionales', 'ASESOR', 'Prestación de Servicios Profesionales para el acompañamiento y representación judicial al Distrito de Santiago de Cali en primera y segunda instancia en todas las actuaciones, etapas procesales y providencias judiciales que se surtan desde el momento que asuma la representación de la entidad en los tres (3) procesos contenciosos administrativos que se adelantan en la actualidad ante el Tribunal Administrativo del Valle del Cauca y el Consejo de Estado, respectivamente, a través del medio de control de controversias contractuales, identificados con las radicados número 76001-23-33-007-2017-01644-00, 76001-23-33-006-2018-00217-00 y 76001-23-33-000-2023-00722-00, en los cuales se pretende la declaratoria de nulidad de los actos administrativos por medio de los cuales se decretó el incumplimiento y la caducidad del contrato de concesión N°4151.1.14.26.005-10 celebrado con la sociedad Vías de Cali S.A.S.', '', 'EJECUCIÓN', 'ENERO-JUNIO', NULL, NULL, NULL, '2026-01-26', '2026-01-26', '2026-01-26', '', 0, 0, 'Doscientos cincuenta y ocho millones doscientos setanta y cuatro mil quinientos cincuenta y tres pesos M/cte', 258274553.00, 217037439.50, 41237113.50, 'Ciento veintinueve millones ciento treinta y siete mil doscientos setenta y seis pesos M/cte', 129137276.00, 'Dos', 2, '', NULL, '', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2240, 318, 31, 2607, 349, '', NULL, NULL, 'Doscientos diecisiete millones treinta y siete mil cuatrocientos treinta y nueve pesos M/cte', 'Cuarenta y uno millones doscientos treinta y siete mil ciento catorce pesos M/cte', '', 108518719.3, '', 20618556.67, 'NO', 0, '', NULL, '', NULL, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.9790148&isFromPublicArea=True&isModal=False', 'SI', 2026, '', NULL, 'NO');
INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2100, '4121.010.32.1.080', '4121.010.26.1.080', 'Prestación de servicios profesionales', 'PROFESIONAL ESPECIALIZADO', 'Profesional de servicios especializado en la elaboración de documentos de estudios previos, requerimientos técnicos y representación judicial requeridos por la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico del Departamento Administrativo de Gestión Jurídica Pública.', '', 'CERRADO', 'ENERO-JUNIO', NULL, NULL, '2026-04-30', '2026-01-28', '2026-01-29', '2026-01-28', 'Treinta (30) de abril del dos mil veintiseis (2026)', 4, 30, 'Veintiún millones ochocientos sesenta y cuatro mil quinientos pesos M/cte', 21864500.00, NULL, NULL, 'Cuatro (4) cuotas; una (1) cuota de Tres millones ciento veintitrés mil quinientos pesos m/cte y tres (3) cuotas de Seis millones doscientos cuarenta y siete mil pesos m/cte', 6247000.00, 'Cuatro', 4, 'Tres millones ciento veintitres mil quinientos pesos M/cte', 3123500.00, '1.Apoyar a la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico del Departamento Administrativo de Gestión Jurídica Pública, en la elaboración  de estudios previos, requerimientos técnicos y demás documentos relacionados con temas de contratación que le sean asignados.2. Ejercer la representación judicial, extrajudicial y de acciones constitucionales de la Entidad que le sean asignados, cumpliendo oportunamente las actuaciones administrativas judiciales y extrajudiciales, asistiendo a las diligencias programadas, agotando los recursos que procedan, reportando oportunamente las fechas de las diligencias programadas en audiencias virtuales o en estrados judiciales, sustentando ante el Comité de Conciliación y Defensa Judicial la estrategia de defensa de los procesos judiciales que le sean asignados y de las actuaciones judiciales que requieran de posición institucional o que impliquen disposición del derecho en litigio. Todo lo anterior conforme a las normas legales vigentes y a los protocolos, instructivos o lineamientos establecidos por el Departamento Administrativo de Gestión Jurídica Pública. 3. Mantener actualizado el sistema de información de registro, control y seguimiento de procesos judiciales, relacionando la actividad desplegada en cada uno de los procesos a su cargo, realizando el cálculo de la provisión contable y la calificación del riesgo procesal en aquellos asuntos judiciales y conciliaciones extrajudiciales asignados. Lo anterior, a efectos de conformar el expediente físico o virtual y mantener la integridad y precisión en el proceso contable. 4. Asistir a las jornadas de socialización, mesas técnicas, mesas de estudio y comités de fortalecimiento a los que sea convocado. 5. Atender las diligencias administrativas, judiciales y extrajudiciales programadas dentro de los 45 días calendarios siguientes al vencimiento del plazo del contrato, correspondientes a los procesos asignados salvo que se presente una causal de inhabilidad o incompatibilidad sobreviniente. 6. Proyectar los conceptos jurídicos, requerimientos y respuestas a solicitudes o peticiones que le sean asignados. 7. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual. Parágrafo. La representación judicial ejercida por el contratista corresponde a una actividad liberal que continúa ejerciendo este en cualquier escenario público o privado durante la ejecución del contrato sin exclusividad o subordinación alguna respecto al Distrito Especial de Santiago de Cali. No obstante, lo anterior, deberá dar cumplimento a las disposiciones consagradas en la Ley 1123 de 2007 (Código Disciplinario del Abogado) en lo que corresponde a deberes e incompatibilidades, especialmente la prohibición de litigio contra la entidad contratante.', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2241, 318, 31, 2608, 343, '', NULL, NULL, '', '', '', NULL, '', NULL, 'SI', 2, 'Diez millones ochocientos veintiocho mil ciento treinta y tres pesos mcte.', 12494000, 'Treinta y cuatro millones trescientos cincuenta y ocho mil quinientos pesos M/cte', 34358500, 'https://community.secop.gov.co/Public/Tendering/OpportunityDetail/Index?noticeUID=CO1.NTC.9824759&isFromPublicArea=True&isModal=False', 'NO', 2026, '', NULL, 'NO');
