INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2126, '4121.010.32.1.187', '4121.010.26.1.187', 'Prestación de servicios de apoyo a la gestión', 'TÉCNICO', 'Prestación de servicios de apoyo a la gestión en la digitación y creación de procesos prejudiciales y judiciales   dentro del aplicativo del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública del Distrito Especial de Santiago de Cali.', '', '', 'NOVIEMBRE-DICIEMBRE', NULL, NULL, '2026-12-30', NULL, NULL, NULL, 'Treinta (30) de diciembre del 2026', 12, 30, 'Siete millones ciento dos mil pesos m/cte', 7102000.00, NULL, NULL, 'Tres millones quinientos cincuenta y un mil pesos m/cte', 3551000.00, 'Dos', 2, '', NULL, '1.Apoyar en la digitación y creación en el aplicativo del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, de las acciones constitucionales que le fueran notificadas al organismo. 2. Apoyar en la digitalización, cargue y actualización en el sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, los documentos inherentes a las actuaciones  constitucionales que le fueran notificadas al organismo. 3. Apoyar en la asignación de acciones constitucionales dentro del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública. 4. Apoyar cuando se le requiera, en las actividades de depuración de acciones de tutelas dentro del aplicativo de sistemas de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública.  5. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2199, 323, 31, 2640, 338, 'GLORIA AMPARO PEREZ PAZ , Asesora', NULL, NULL, '', '', '', NULL, '', NULL, 'NO', 0, '', NULL, '', NULL, '', 'NO', 2026, '', NULL, 'NO');
INSERT INTO public.contratos (id, trd_proceso, numero_contrato, tipo_contrato, nivel, objeto, modalidad, estado, periodo, fecha_suscripcion, fecha_inicio, fecha_terminacion, fecha_aprobacion, fecha_ejecucion, fecha_arl, plazo_ejecucion, plazo_meses, plazo_dias, valor_total_letras, valor_total_numeros, valor_antes_iva, valor_iva, valor_cuota_letras, valor_cuota_numero, num_cuotas_letras, num_cuotas_numero, valor_media_cuota_letras, valor_media_cuota_numero, actividades_entregables, liquidacion_acuerdo, liquidacion_articulo, liquidacion_decreto, circular_honorarios, contratista_id, supervisor_id, ordenador_id, presupuesto_id, estructurador_id, apoyo_supervision, fecha_idoneidad, fecha_estructurador, valor_antes_iva_letras, valor_iva_letras, valor_cuota_antes_iva_letras, valor_cuota_antes_iva, valor_cuota_iva_letras, valor_cuota_iva, adicion_si_no, numero_cuotas_adicion, valor_total_adicion_letras, valor_total_adicion, valor_contrato_mas_adicion_letras, valor_contrato_mas_adicion, enlace_secop, iva_si_no, anio, numero_modificacion, fecha_modificacion, facturador_electronico) VALUES (2127, '4121.010.32.1.188', '4121.010.26.1.188', 'Prestación de servicios profesionales', 'PROFESIONAL', 'Prestación de servicios profesionales como Abogado Especializado, brindando soporte en la realización de las actividades de defensa judicial y administrativas desarrolladas en la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico  del Distrito Especial de Santiago de Cali', '', '', 'NOVIEMBRE-DICIEMBRE', NULL, NULL, '2026-12-30', NULL, NULL, NULL, 'Treinta (30) de diciembre del 2026', 12, 30, 'Doce millones cuatrocientos noventa y cuatro mil pesos m/cte', 12494000.00, NULL, NULL, 'Seis millones doscientos cuarenta y siete mil pesos m/cte', 6247000.00, 'Dos', 2, '', NULL, '1.Ejercer la representación judicial de los intereses del Distrito Especial de Santiago de Cali, cuando sea requerido. 2. Realizar el cargue de las sentencias favorables en el sistem "sinfonia" para actualizar el precedente judicial . 3.Brindar apoyo profesional en la revisión de fichas técnicas, convocatorias y organización de las sesiones del Comité de Conciliación y Defensa Judicial. 4. Proyectar las actas de reunión de las sesiones ordinarias y extraordinarias que realice el Comité de Conciliación y Defensa Judicial del Distrito Especial de Santiago de Cali. 5. Proyectar las actas del Comité de Conciliación y Defensa Judicial del Distrito Especial de Santiago de Cali que deban presentar los apoderados judiciales dentro de las etapa prejudiciales y judiciales donde el Distrito Especial de Santiago de Cali se encuentre vinculado. 6.Proyectar los informes que el Comité de Conciliación y Defensa Judicial debe presentar al señor Alcalde del Distrito de Santiago de Cali y Órganos de Control 7. Las demás actividades que le asigne el supervisor del contrato y que se encuentren relacionadas con el objeto del mismo.', '', '', '', 'No. 202541350100008374 del 21 de diciembre del 2025 con Alcance No. 202641350200000024 del 05 de enero del 2026', 2205, 323, 31, 2641, 338, 'GLORIA AMPARO PEREZ PAZ , Asesora', NULL, NULL, '', '', '', NULL, '', NULL, 'NO', 0, '', NULL, '', NULL, '', 'NO', 2026, '', NULL, 'NO');
