INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (12, 2055, '2026-04', 'PARCIAL', '4', '2026-01-10', '2026-06-30', E'Modificación No. 001 del 17 de abril de 2026 mediante la cual las partes acordaron: PRORROGAR el Contrato de Prestación de servicios de apoyo a la gestión No. 4121.010.26.1.035-2026 hasta el 30 de junio de 2026; y ADICIONAR el Contrato de Prestación de servicios de apoyo a la gestión No. 4121.010.26.1.035-2026 por la suma de SIETE MILLONES CIENTO DOS MIL PESOS M/CTE ($7.102.000). Dicha adición se pagará en dos (2) cuotas iguales, cada una de ellas por valor de tres millones quinientos cincuenta y un mil pesos m/cte ($3.551.000).\r\n\r\nPor lo tanto, el valor total del contrato queda en la suma de VEINTIÚN MILLONES TRESCIENTOS SEIS MIL PESOS M/CTE ($21.306.000).', 'N/A', 'N/A', 'N/A', 'N/A', 3551000.00, 10653000.00, 0.00, '9501980650', '15110711', 'Aportes en línea', '2026-04-06', '2026-03', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-07-30 18:36:05.765133', '2026-04-24', 'Mediante Modificación No. 001 del 17 de abril de 2026 se adiciona la suma SIETE MILLONES CIENTO DOS MIL PESOS M/CTE ($7.102.000).', 'Mediante Modificación No. 001 del 17 de abril de 2026 se prorroga el Contrato de Prestación de servicios de apoyo a la gestión 4121.010.26.1.035-2026 hasta el 30 de junio de 2026.', 'N/A', 'N/A', E'[{"obligacion":"1.Apoyar en la digitación y creación en el aplicativo del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, de las acciones constitucionales que le fueran notificadas al organismo.","actividad":"<p style=\\"text-align: justify;\\"><span style=\\"font-family:\\" arial,sans-serif;<br=\\"\\">Apoyó en la digitación y creación en el&nbsp;aplicativo del sistema de información de procesos judiciales del departamento&nbsp;administrativo de gestión jurídica pública, de los procesos prejudiciales, un&nbsp;total de 182 tutelas.<\\/span><\\/p>"},{"obligacion":"2. Apoyar en la digitalización, cargue y actualización en el sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública, los documentos inherentes a las actuaciones  constitucionales que le fueran notificadas al organismo.","actividad":"<p style=\\"text-align: justify;\\"><span style=\\"font-family:\\" arial,sans-serif;<br=\\"\\">Apoyó en la digitalización, cargué y&nbsp;actualización en el sistema de información de procesos judiciales del&nbsp;Departamento Administrativo de Gestión Jurídica Pública un total de 17&nbsp;sentencias de primera instancia.<\\/span><\\/p>"},{"obligacion":"3. Apoyar en la asignación de acciones constitucionales dentro del sistema de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\"><span sans-serif;=\\"\\">Apoyó en la asignación de acciones&nbsp;constitucionales dentro del sistema de información de procesos judiciales del&nbsp;Departamento Administrativo de Gestión Jurídica Pública un total de 182&nbsp;asignaciones a los diferentes organismos.<\\/span><\\/p>"},{"obligacion":"4. Apoyar cuando se le requiera, en las actividades de depuración de acciones de tutelas dentro del aplicativo de sistemas de información de procesos judiciales del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\"><span style=\\"font-family:\\" arial,sans-serif;<br=\\"\\">Apoyó seguimiento en las actividades de&nbsp;depuración del aplicativo de sistemas de información de procesos judiciales del&nbsp;Departamento Administrativo de Gestión Jurídica Pública dando terminación un&nbsp;total de 17 tutelas que se encontraban activas del año 2024.<\\/span><\\/p>"},{"obligacion":"5. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.","actividad":"<p style=\\"text-align: justify;\\"><span style=\\"font-family:\\" arial,sans-serif;=\\"\\" es-co;=\\"\\">Asistió a capacitación de primeros auxilios&nbsp;psicológicos.<\\/span><\\/p>"}]', 'https://drive.google.com/drive/folders/1YRJD_FGtcb5OvmccOddDNpJUWZFCcWxt?usp=sharing', '0276', '{"evidencia_3_0":{"name":"Registro de planilla de creación .jpeg","id":"1PCEzVku9Jac_7bf2q1ESjbSKpDqZp-ce","url":"https://drive.google.com/file/d/1PCEzVku9Jac_7bf2q1ESjbSKpDqZp-ce/view"},"evidencia_3_0_1":{"name":"sentencias subidas en el aplicativo elcy febrero.xlsx","id":"1JOQmMCVjwZ426w5sm-SLlkiEk2PQcK1j","url":"https://drive.google.com/file/d/1JOQmMCVjwZ426w5sm-SLlkiEk2PQcK1j/view"},"evidencia_2_0":{"name":"Registro de planilla de creación .jpeg","id":"1Scu-sIJraAJtA1S4FdHG6tmAfKjCQJif","url":"https://drive.google.com/file/d/1Scu-sIJraAJtA1S4FdHG6tmAfKjCQJif/view"},"evidencia_0_0":{"name":"orfeo cuota 4.jpeg","id":"1OhbDZtQY1sBYxXdpJYnRIdqgpMYxrrCx","url":"https://drive.google.com/file/d/1OhbDZtQY1sBYxXdpJYnRIdqgpMYxrrCx/view"},"evidencia_1_0":{"name":"Registro de planilla de creación .jpeg","id":"1DtQRVIi9W9qHxri0XVh_m3GC2CrHb87v","url":"https://drive.google.com/file/d/1DtQRVIi9W9qHxri0XVh_m3GC2CrHb87v/view"},"file_paz_salvo_orfeo":{"name":"Paz y salvo orfeo Cuota No. 4.jpeg","id