INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (72, 1958, '2026-09', 'PARCIAL', '3', '2026-07-07', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 3551000.00, 7102000.00, 10653000.00, '1083999730', '8810669465', 'SIMPLE', '2026-09-14', '2026-08', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-01 10:00:43.587928', '2026-09-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar apoyo en la construcción y elaboración de las presentaciones que le sean encomendadas.","actividad":"<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">-Brindó apoyo en la construcción y elaboración de las presentaciones utilizadas como material de apoyo para la exposición de la Directora del Departamento Administrativo de Gestión Jurídica Pública ante el Concejo Distrital de Santiago de Cali, relacionadas con los siguientes proyectos de acuerdo:<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<ul style=\\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\\">\\n <li dir=\\"ltr\\" style=\\"list-style-type:disc;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\\" aria-level=\\"1\\">\\n  <p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\" role=\\"presentation\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">\\u201cPOR EL CUAL SE ESTABLECEN MEDIDAS TRIBUTARIAS Y NO TRIBUTARIAS DE CARÁCTER EXCEPCIONAL Y TEMPORAL CON OCASIÓN DE LA SITUACIÓN DE DESASTRE DE CARÁCTER NACIONAL DECLARADA MEDIANTE EL DECRETO 1171 DEL 11 DE AGOSTO DE 2026 Y DE LA SITUACIÓN DE CALAMIDAD PÚBLICA DECLARADA MEDIANTE EL DECRETO DISTRITAL 4112.010.20.0963 DEL 10 DE AGOSTO DE 2026, SE MODIFICAN LOS ARTÍCULOS 96 Y 307 DEL ACUERDO 643 DE 2026 EN LO PERTINENTE Y SE DICTAN OTRAS DISPOSICIONES\\u201d.<\\/span><\\/p><\\/li>\\n<\\/ul>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<ul style=\\"margin-top:0;margin-bottom:0;padding-inline-start:48px;\\">\\n <li dir=\\"ltr\\" style=\\"list-style-type:disc;color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;\\" aria-level=\\"1\\">\\n  <p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\" role=\\"presentation\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">\\u201cPOR EL CUAL SE MODIFICA EL PRESUPUESTO GENERAL DE RENTAS Y RECURSOS DE CAPITAL Y APROPIACIONES PARA GASTOS DEL DISTRITO DE SANTIAGO DE CALI, PARA LA VIGENCIA FISCAL COMPRENDIDA ENTRE EL 1 DE ENERO Y 31 DE DICIEMBRE DEL AÑO 2026, EXPEDIDO POR EL ALCALDE MEDIANTE DECRETO 4112.010.20.1049 DEL 17 DE DICIEMBRE DE 2025\\u201d.<\\/span><\\/p><\\/li>\\n<\\/ul>"},{"obligacion":"2. Brindar apoyo en los procesos de Nacionalización.","actividad":"<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100029921 del 26 de agosto del 2026 mediante la cual dio respuesta al derecho de petición radicado en el sistema de gestión documental ORFEO No. 202641730101742472, relacionado con el estado del trámite de adquisición de la nacionalidad colombiana por adopción, informando sobre la recepción de la Carta de Naturaleza remitida por el Ministerio de Relaciones Exteriores y la programación de la toma de juramento para el 14 de agosto de 2026, así como sobre la cancelación de dicha diligencia debido a la contingencia generada por el sismo ocurrido el 10 de agosto de 2026 y las medidas de seguridad adoptadas en las instalaciones de la Alcaldía Distrital de Santiago de Cali.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100029931 del 26 de agosto del 2026 mediante la cual dio respuesta a la solicitud radicada bajo el No. 202641730102011992, relacionada con el estado del trámite para la toma de juramento como colombiana por adopción, informando el procedimiento requerido para que la Alcaldía Distrital de Santiago de Cali pueda adelantar la respectiva diligencia, así como la necesidad de recibir oficialmente del Ministerio de Relaciones Exteriores la Resolución No. 07881 del 11 de junio de 2026, mediante la cual se concede la nacionalidad colombiana por adopción, para posteriormente realizar las actuaciones administrativas correspondientes y efectuar la citación a la toma de juramento.<\\/span><\\/p>\\n\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100030391 del 28 de agosto del 2026 mediante la cual dio respuesta a la solicitud radicada bajo el No. 202641730102105752, relacionada con el trámite para la toma de juramento como colombiano por adopción, informando el procedimiento administrativo requerido para adelantar la respectiva diligencia y precisando que es necesario que el Ministerio de Relaciones Exteriores remita oficialmente a la Alcaldía Distrital de Santiago de Cali la Carta de Naturaleza mediante la cual se concede la nacionalidad colombiana por adopción, para posteriormente realizar la programación y correspondiente citación a la toma de juramento.<\\/span><\\/p>"},{"obligacion":"3. Brindar apoyo al desarrollo de las actividades administrativas en centro de documentación y correspondencia del Departamento Administrativo de Gestión Jurídica Pública del Distrito Especial de Santiago de Cali.","actividad":"<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Realizó el despacho de comunicaciones oficiales, decretos, circulares y acciones de tutela suscritas o revisadas por la Directora, utilizando el Sistema de Gestión Documental ORFEO.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Envío veintiséis (26) contestaciones de acciones de tutela, debidamente suscritas por la Directora del Departamento Administrativo de Gestión Jurídica Pública, al correo institucional dispuesto para la recepción de notificaciones judiciales y de acciones de tutela, con el fin de que fueran remitidas y notificadas oportunamente a los respectivos despachos judiciales en representación del Distrito de Santiago de Cali.<\\/span><\\/p>\\n\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Remitió ocho (8) respuestas a derechos de petición, mediante correo electrónico, para su correspondiente trámite de notificación y envío a los respectivos peticionarios a través del correo electrónico certificado<\\/span><\\/p>"},{"obligacion":"4. Recibir y organizar los documentos internos y externos dirigidos al Departamento Administrativo de Gestión Jurídica Pública, en el marco del proceso de Gestión documental.","actividad":"<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">&nbsp;Recibió comunicaciones oficiales, proyectos de decretos, circulares y contestaciones de acciones de tutelas para firma o visto bueno de la Directora del Departamento Administrativo de Gestión Jurídica Pública.<\\/span><\\/p>\\n<p><span><br><\\/span><\\/p>\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Verificó que cada documento estuviera debidamente radicado en el Sistema de Gestión Documental ORFEO, así como que contará con los vistos buenos necesarios&nbsp; antes de continuar con su trámite de revisión y posterior firma o visto bueno de la Directora del Departamento Administrativo de Gestión Jurídica Pública .<\\/span><\\/p>"},{"obligacion":"5. Realizar la clasificación de las comunicaciones oficiales recibidas por el Sistema de gestión documental del Distrito, re direccionando de acuerdo a la instrucción del Director del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p dir=\\"ltr\\" style=\\"margin-left: 3.6pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Realizó el reparto y re direccionamiento de las comunicaciones oficiales recibidas en el usuario DESPACHO.JURIDICAPUBLICA del Sistema de Gestión Documental ORFEO a las diferentes subdirecciones del Departamento Administrativo de Gestión Jurídica Pública, de conformidad con las instrucciones impartidas por la Directora.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-left: 3.6pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Brindó apoyo en el traslado a las dependencias competentes de las comunicaciones oficiales recibidas en el usuario DESPACHO.JURIDICAPUBLICA del Sistema de Gestión Documental ORFEO para su atención.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-left: 3.6pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Garantizó la oportuna distribución de los asuntos para evitar retrasos en los términos administrativos y judiciales.<\\/span><\\/p>\\n\\n<p dir=\\"ltr\\" style=\\"margin-left: 3.6pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><a href=\\"https://docs.google.com/spreadsheets/d/1sxuYTki5iivO354CUQprM-QP4HfGbRavOdpUoaeaSBs/edit?usp=drive_link\\" style=\\"text-decoration:none;\\"><span style=\\"color:#1155cc;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:underline;-webkit-text-decoration-skip:none;text-decoration-skip-ink:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">https://docs.google.com/spreadsheets/d/1sxuYTki5iivO354CUQprM-QP4HfGbRavOdpUoaeaSBs/edit?usp=drive_link<\\/span><\\/a><\\/p>"},{"obligacion":"6. Realizar la depuración del sistema de gestión documental Orfeo.","actividad":"<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Realizó la depuración del Sistema de Gestión Documental ORFEO mediante el cargue de las constancias de envío de 27 comunicaciones oficiales remitidas a los diferentes despachos judiciales en atención a incidentes de desacato.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Efectuó el archivo de 14 comunicaciones oficiales radicadas en el Sistema de Gestión Documental ORFEO, de conformidad con las solicitudes efectuadas por los diferentes usuarios.<\\/span><\\/p>\\n\\n<p dir=\\"ltr\\" style=\\"text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><a href=\\"https://docs.google.com/spreadsheets/d/1uA0PQBWweDzno7XX_7pnmv5zyxcLZlfwB6nTE_GpYuo/edit?usp=drive_link\\" style=\\"text-decoration:none;\\"><span style=\\"color:#1155cc;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:underline;-webkit-text-decoration-skip:none;text-decoration-skip-ink:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">https://docs.google.com/spreadsheets/d/1uA0PQBWweDzno7XX_7pnmv5zyxcLZlfwB6nTE_GpYuo/edit?usp=drive_link<\\/span><\\/a><\\/p>"},{"obligacion":"7. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.","actividad":"<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100029901 del 26 de agosto del 2026 mediante la cual solicitó la ampliación de información respecto del derecho de petición radicado ORFEO No. 202641730102086782, teniendo en cuenta que, una vez revisado su contenido, no fue posible identificar de manera clara y precisa el objeto de la solicitud, toda vez que la comunicación se encontraba orientada a informar sobre presuntas fallas presentadas en la plataforma de radicación de PQRS, sin precisar concretamente la actuación, información o trámite requerido.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100029891 del 26 de agosto del 2026 mediante la cual solicitó la ampliación de información respecto del derecho de petición radicado ORFEO No. 202641730102099622, teniendo en cuenta que, una vez revisada la información recibida, no fue posible identificar de manera clara, concreta y precisa el objeto de la solicitud, ni establecer con certeza la actuación administrativa, información o respuesta pretendida por el peticionario.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100066424 del 11 de septiembre del 2026&nbsp; mediante la cual solicitó la asignación de tarjetas de proximidad para el ingreso al edificio CAM a los contratistas que prestan sus servicios profesionales y/o de apoyo a la gestión en el Departamento Administrativo de Gestión Jurídica Pública, cuyos contratos de prestación de servicios fueron suscritos durante el mes de agosto de 2026, de acuerdo con el listado de contratistas relacionado en la solicitud.&nbsp;<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100033231 del 11 de septiembre de 2026, dirigida a la Coordinadora del Grupo SUI de la Superintendencia Delegada para Acueducto, Alcantarillado y Aseo, mediante la cual informó el traslado por competencia efectuado a la Unidad Administrativa Especial de Servicios Públicos \\u2013 UAESP del Distrito Especial de Santiago de Cali, respecto del requerimiento SSPD Rad. No. 20264034432211 del 8 de septiembre de 2026, relacionado con la visita de reconocimiento y caracterización del área de prestación de la organización Asociación Colombiana de Recuperadores Ambientales del Servicio Público de Aseo \\u2013 ID 68639, indicando que la UAESP deberá adelantar las actuaciones correspondientes y atender directamente el requerimiento dentro de los términos legales.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100033341 del 11 de septiembre de 2026, mediante la cual trasladó por competencia la petición presentada por la señora Gladys María Acevedo Mellizo, relacionada con la prescripción de obligaciones correspondientes a la prestación de los servicios públicos domiciliarios del suscriptor No. 327966, a EMCALI E.I.C.E. E.S.P. para su conocimiento y trámite, de conformidad con lo dispuesto en el artículo 21 de la Ley 1437 de 2011, sustituido por el artículo 1° de la Ley 1755 de 2015, solicitando adelantar las actuaciones correspondientes y emitir respuesta de fondo a la peticionaria.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100033381 del 11 de septiembre de 2026, &nbsp; mediante la cual informó a la peticionaria el traslado por competencia de su solicitud a EMCALI E.I.C.E. E.S.P, mediante Oficio No. 202641210100033341, relacionada con la prescripción de obligaciones correspondientes a la prestación de los servicios públicos domiciliarios del suscriptor No. 327966, teniendo en cuenta que las pretensiones formuladas correspondían a asuntos propios de la competencia de dicha entidad, de conformidad con el artículo 21 de la Ley 1437 de 2011, sustituido por el artículo 1° de la Ley 1755 de 2015.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100034681, del 16 de septiembre de 2026, mediante el cual trasladó por competencia a la Defensoría del Pueblo \\u2013 Regional Valle del Cauca, la petición radicada bajo el No. 202641730102300492, relacionada con la presunta afectación del derecho a la libertad de expresión de un creador de contenido identificado como Samuel Adrián, para que, en el marco de sus competencias constitucionales y legales, valorará los hechos expuestos y determinara las actuaciones a que hubiera lugar, de conformidad con el artículo 21 de la Ley 1437 de 2011, sustituido por el artículo 1 de la Ley 1755 de 2015.<\\/span><\\/p>\\n<p><b style=\\"font-weight:normal;\\"><br><\\/b><\\/p>\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad.202641210100034671 del 16 de septiembre de 2026, mediante la cual informó al peticionario sobre el traslado por competencia de la petición radicada bajo el No. 202641730102300492 a la Defensoría del Pueblo \\u2013 Regional Valle del Cauca, indicando que los asuntos planteados se encontraban relacionados con la protección y defensa de derechos humanos y libertades fundamentales, materias que no corresponden a la competencia del Departamento Administrativo de Gestión Jurídica Pública, y señalando que el traslado se efectuó mediante Oficio Rad. No. 202641210100034681.<\\/span><\\/p>\\n\\n<p dir=\\"ltr\\" style=\\"margin-right: 17.75pt;text-align: justify;margin-top:0pt;margin-bottom:0pt;\\"><span style=\\"color:#000000;background-color:transparent;font-weight:400;font-style:normal;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;\\">- Elaboró la comunicación oficial Rad. No. 202641210100034511, de fecha 16 de septiembre de 2026, mediante la cual dio respuesta a la solicitud radicada bajo el No. 202641730102310672, relacionada con la consulta del número de radicado de un derecho de petición previamente presentado, informando que, una vez realizada la consulta en el Sistema de Gestión Documental ORFEO, se identificó el radicado No. 202641730101800102, con fecha de radicación 28 de julio de 2026.<\\/span><\\/p>"}]', 'https://drive.google.com/drive/folders/1aWrgiMZsOgZVsmyOB8uEi1npnkwAyjPD?usp=sharing', '0656', '{"evidencia_2_0":{"name":"Resultados de la búsqueda - tutelas enviadas (1).pdf","id":"18Xl44re7pG5LRwVJNdjOsBjKuj65GZOs","url":"https://drive.google.com/file/d/18Xl44re7pG5LRwVJNdjOsBjKuj65GZOs/view"},"evidencia_0_0":{"name":"ACTIVIDAD 1-20261001T150822Z-1-001.zip","id":"1M4zeIwlWnTj4eB1g1xd7tOiIM69Pe8gU","url":"https://drive.google.com/file/d/1M4zeIwlWnTj4eB1g1xd7tOiIM69Pe8gU/view"},"evidencia_1_0":{"name":"ACTIVIDAD 2-20261001T151554Z-1-001.zip","id":"1xzOIkZm6FSnAkT8ve_VjtS1QIi-vjDOl","url":"https://drive.google.com/file/d/1xzOIkZm6FSnAkT8ve_VjtS1QIi-vjDOl/view"},"evidencia_6_0":{"name":"ACTIVIDAD 7-20261001T151052Z-1-001.zip","id":"1qy8t6CWvTi0M4Ws-BR0FJeUlQVHRC5yJ","url":"https://drive.google.com/file/d/1qy8t6CWvTi0M4Ws-BR0FJeUlQVHRC5yJ/view"},"evidencia_5_0":{"name":"Hoja de cálculo sin título (6).xlsx","id":"1XyX0wOF5Xd5zbgQ43eHKp9YyjWbEdrYS","url":"https://drive.google.com/file/d/1XyX0wOF5Xd5zbgQ43eHKp9YyjWbEdrYS/view"},"evidencia_4_0":{"name":"REPARTO (1).xlsx","id":"1Y8e5uq-PZeTlIXkN7arN8rKSuW9A6ZBH","url":"https://drive.google.com/file/d/1Y8e5uq-PZeTlIXkN7arN8rKSuW9A6ZBH/view"},"file_seguridad_social":{"name":"4. SEGURIDAD SOCIAL CUOTA 3 - ESTEFANIA QUINTERO. SEGURIDAD SOCIAL CUOTA 3 Estefanía Molina","id":"1kRb9TJ1dJ8qI2F-wCL14DcvlvoAy7BOR","url":"https://drive.google.com/file/d/1kRb9TJ1dJ8qI2F-wCL14DcvlvoAy7BOR/view"},"file_rpc":{"name":"1. RPC - ESTEFANIA QUINTERO.pdf","id":"1bUr7OSdzg5EsiZH6oXvZyEwo8o0uqIve","url":"https://drive.google.com/file/d/1bUr7OSdzg5EsiZH6oXvZyEwo8o0uqIve/view"}}', 'APROBADA PARA IMPRESION', 14, NULL, '', '', 2026, '', '', '', 'NO', 314, NULL, NULL);
