INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (75, 1943, '2026-07', 'PARCIAL', '1', '2026-07-07', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 2271000.00, 0.00, 11355000.00, '1082378888', '1082378888', 'SIMPLE', '2026-06-25', '2026-06', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-01 10:53:03.997985', '2026-07-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Clasificar y archivar los diversos documentos que le sean encomendados, especialmente producto de la gestión de las cajas menores.","actividad":"<p>Para este periodo no se clasificó ni archivo documentos relacionados con la caja menor.<\\/p>"},{"obligacion":"2. Apoyar en el suministro de insumos de oficina y en la gestión del almacén del organismo.","actividad":"<p>Brindó apoyo en el levantamiento del inventario de equipos de cómputo y en la verificación<\\/p>\\n<p>de la información registrada en la sección ZAM_ACTIVOS del aplicativo SAP, validando el<\\/p>\\n<p>responsable asignado a cada equipo.<\\/p>"},{"obligacion":"3. Apoyar en el seguimiento de los consumos de combustible del parque automotor del organismo.","actividad":"<p>Brindó apoyo en la recepción de los comprobantes correspondientes al consumo de<\\/p>\\n<p>combustible del parque automotor asignado al Departamento, así como en su clasificación y<\\/p>\\n<p>organización. Estas actividades se llevaron a cabo con el fin de mantener un mecanismo de<\\/p>\\n<p>control que facilite la conciliación de la información con el área competente de la Unidad<\\/p>\\n<p>Administrativa Especial de Gestión de Bienes y Servicios del Distrito. A continuación, se<\\/p>\\n<p>relacionan los comprobantes entregados por el personal responsable de la conducción de los<\\/p>\\n<p>vehículos oficiales durante el mes de JULIO de 2026.<\\/p>"},{"obligacion":"4. Escanear documentos, tomar fotocopias, atender al público y realizar las actividades de apoyo al proceso que le sean requeridas","actividad":"<p>Brindó apoyo en el escaneo de los informes de supervisión de los contratistas que pasaron la<\\/p>\\n<p>cuenta de cobro del mes de JULIO de 2026, relacionados a continuación:<\\/p>"},{"obligacion":"5. Atender las demás solicitudes que realice el (la) Director (a) del el Departamento Administrativo de Gestión Jurídica Pública y supervisor relacionadas con el objeto del contrato","actividad":"<p>Para este periodo no se realizaron actividades asignadas por la Directora del Departamento.<\\/p>"}]', 'https://drive.google.com/drive/folders/1jNPtu49BUhz2nKrrSpH3vTQ7m514667F?usp=sharing', '0483', '{"evidencia_1_0":{"name":"INVENTARIO (2).xlsx","id":"1NcN0r6nLV_Otpo9iTDUACNDSZ7qvXxs6","url":"https://drive.google.com/file/d/1NcN0r6nLV_Otpo9iTDUACNDSZ7qvXxs6/view"},"file_rut":{"name":"7. RUT - PABLO CAMILO.pdf","id":"1Ny8UclGFBe7zkPGthYELyH0d8Z97ODGh","url":"https://drive.google.com/file/d/1Ny8UclGFBe7zkPGthYELyH0d8Z97ODGh/view"},"file_secop":{"name":"2. CONTRATO SECOP II - PABLO CAMILO.pdf","id":"1QQJoLxrJgX1NpW0KhNRQw2Ad-HhWjJtr","url":"https://drive.google.com/file/d/1QQJoLxrJgX1NpW0KhNRQw2Ad-HhWjJtr/view"},"file_cedula":{"name":"6. CEDULA - PABLO CAMILO.pdf","id":"1dC9RxjG307rQfKOR_NS4kHhAwEBmVtAX","url":"https://drive.google.com/file/d/1dC9RxjG307rQfKOR_NS4kHhAwEBmVtAX/view"},"file_seguridad_social":{"name":"8. SEGURIDAD SOCIAL CUOTA 1 - PABLO CAMILO.pdf","id":"1tQu8gBKNXJMv8NJ4X40I3lcNaHMm7Yje","url":"https://drive.google.com/file/d/1tQu8gBKNXJMv8NJ4X40I3lcNaHMm7Yje/view"},"file_ficha_tecnica":{"name":"4. FICHA TECNICA - PABLO CAMILO.pdf","id":"1WwvLNXvk2ejJP-8BQ8RBCsujSSTbuBt-","url":"https://drive.google.com/file/d/1WwvLNXvk2ejJP-8BQ8RBCsujSSTbuBt-/view"},"file_rpc":{"name":"1. RPC - PABLO CAMILO.pdf","id":"1AJUdOdJGMQqiwDQNZoBxGuRQmWrWdtf0","url":"https://drive.google.com/file/d/1AJUdOdJGMQqiwDQNZoBxGuRQmWrWdtf0/view"}}', 'APROBADA PARA IMPRESION', 14, NULL, '', '', 2026, NULL, NULL, NULL, 'NO', 315, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (76, 1941, '2026-07', 'PARCIAL', '1', '2026-07-03', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 5663000.00, 0.00, 28315000.00, '37967592', '824202', 'ASOPAGOS', '2026-07-07', '2026-07', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-01 11:22:16.978377', '2026-07-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar soporte  a las actividades del proceso de Gestión Contractual del Organismo, en lo relacionado con el trámite de afiliación de los contratistas de prestación de servicios profesionales y/o de apoyo a la gestión - personas naturales, a la Aseguradora de Riesgos Laborales \\u2013 ARL a la cual se encuentra afiliada el Distrito Especial de Santiago de Cali.","actividad":"<p style=\\"text-align: justify;\\"><span>Brindó apoyo en la remisión de 64 solicitudes de afiliación de los contratistas vinculados mediante contrato de prestación de servicios profesionales y/o de apoyo a la gestión<\\/span><span>&nbsp; <\\/span><span>personas naturales, a la Aseguradora de Riesgos Laborales \\u2013 ARL.<\\/span><span>&nbsp; <\\/span><span>De los Contratos<\\/span><span>&nbsp; <\\/span><span>085 al 158 Y 164<\\/span>\\n <\\/p>"},{"obligacion":"2. Brindar soporte en la actualización del aplicativo de Gestión de Contratación incorporando todos los documentos expedidos en el desarrollo de la gestión contractual necesarios para el trámite de elaboración de RPC y Fichas Técnicas.","actividad":"<p style=\\"text-align: justify;\\"><span>Digitalizó y actualizó los documentos de los contratos<\\/span><span>&nbsp; <\\/span><span>085 al 158 Y 164 celebrados en la vigencia 2026, los cuales reposan en el aplicativo de gestión contratista<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span>Digitalizó y actualizó en el aplicativo gestión contratistas los documentos de ARL, RPC y demás documentos escaneados en la plataforma SIGEP, correspondiente a los contratos de prestación de servicios del 085 al 158 Y 164 de la vigencia 2026.<\\/span><\\/p>"},{"obligacion":"3. Elaborar el informe de cuentas presentadas para la liberación de RPC que realiza el Organismo, previo envío al Departamento de Hacienda.","actividad":"<p style=\\"text-align: justify;\\"><span>Proyectó el documento en Excel para el proceso liberación cuenta bancaria número de RPC de las cuentas en el mes de Julio del 2026 del Departamento Administrativo de Gestión Jurídica Pública.<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span><span>-<span>&nbsp;<\\/span><\\/span><\\/span><span>Actualizo la base de datos suministrada por el Departamento Administrativo de Hacienda referente a la información del registro presupuestal de compromiso (RPC) para la verificación en SAP de su cuota en las cuentas bancarias de los contratistas del DAGJP contrato 085, al 158 y 164<span>&nbsp; <\\/span>del 2026.<\\/span><\\/p>"},{"obligacion":"4. Revisión y alistamiento de la  información requerida correspondiente a los contratos de prestación de servicios para la realización del reporte mensual al SIA OBSERVA.","actividad":"<p style=\\"text-align: justify;\\"><span>Organizó los documentos requeridos para el reporte mensual al SIA OBSERVA, de los informes de supervisión, informes de gestión, y seguridad social, de las cuentas 001 al 082 de JUNIO 2026, la cual se envía por correo electrónico a la profesional María Eugenia González Espinosa.<\\/span><\\/p>"},{"obligacion":"5. Realizar los registros necesarios en el sistema de gestión financiera (SAP) para el funcionamiento del organismo cuando se le requiera.","actividad":"<p style=\\"text-align: justify;\\"><span>Brindo apoyo en el cargue cuota 1 del mes de julio en la ME23 SAP, respectiva digitalización de los informes de gestión, documento equivalente, seguridad social, de los contratos del 2026.<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <\\/span><\\/span><\\/span><span>Del 085 al 158 y 164 del 2026.<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span>Brindó apoyo en el manejo del aplicativo Sistemas de Aplicaciones y Productos (SAP) alimentando la información requerida en las cuentas por pagar presentadas por los contratistas del Departamento Administrativo de Gestión Jurídica Publica, en las Transacción ZCTRL_00, ZCTRL_ 01. De igual forma se lleva a cabo la trazabilidad de las cuentas a través de la transacción ZCTRL_02.<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span><span>-<span>&nbsp;<\\/span><\\/span><\\/span><span>Apoyó el trámite de liberación de 30 cuentas en el Sistemas de Aplicaciones y Productos (SAP) que se realizan en MIGO, con RPC, la posición y la verificación <\\/span><span>del número<span> de aprobación (SAP)<\\/span>.<\\/span><\\/p>"},{"obligacion":"6. Brindar apoyo en todas las acciones presupuestales que le sean asignadas.","actividad":"<p style=\\"text-align: justify;\\"><span>Actualizo la base de datos suministrada por el Departamento Administrativo de Hacienda referente a la información de las cuentas bancarias y el número del RPC de los contratistas del DAGJP contratos 110, y 155, 156 del 2026 en la plataforma web, de prestación de servicios y/o de apoyo a la gestión del organismo: número de RPC certificado bancario, cédula ciudadanía y Rut.<\\/span>\\n <\\/p>"},{"obligacion":"7. Brindar soporte en las actividades técnicas para el recibo y entrega de los elementos que ingresan al almacén del organismo, que le permitan la elaboración de informes de inventario y ajustes de almacén en el sistema SAP.","actividad":"<p style=\\"text-align: justify;\\"><span>Brindó apoyo en la entrega de 45 elementos o implementos de trabajo, que se relacionan bajo un formato de consumo de oficina por áreas, donde se detalla las necesidades que tienen cada área designada, para el descargue del inventario en sistema SAP, tales como lapiceros, resmas de papel, café, azúcar y demás elementos, para el funcionamiento del Departamento Administrativo de Gestión Jurídica Pública.<\\/span>\\n <\\/p>"},{"obligacion":"8.  Realizar la verificación presupuestal y contable de cuentas de cobro presentadas por los prestadores de servicio  y proveedores del organismo que le sean asignadas.","actividad":"<p style=\\"text-align: justify;\\"><span>-<\\/span><span>&nbsp;&nbsp; <\\/span><span>Apoyó el trámite de 60 cuentas por pagar del mes de Julio, de los contratos con su respectiva verificación de firmas y documentos los cuales se relacionan en las carpetas de contratación 2026 y en la carpeta de evidencia.<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span><span>-<span>&nbsp;<\\/span><\\/span><\\/span><span>Brindó apoyo en la organización de los informes de supervisión del mes Julio y anexos en el aplicativo SAP de los contratos 085 al 158 y 164 del 2026 correspondientes a los contratos de prestación de servicios profesionales y de apoyo a la gestión celebrados por el organismo, así como su digitalización para el respectivo archivo físico y digital, y se procede a verificar<span>&nbsp; <\\/span>en SAP el estado de la cuenta presupuestal en la ZCTRL_01 Y ZCTRL_02, de los contratos enviados.<\\/span><\\/p>"},{"obligacion":"9. Incorporación de documentos de las cuentas de cobro de prestadores de servicios y proveedores en el sistema SGAFT - SAP.","actividad":"<p style=\\"text-align: justify;\\"><span>Apoyó en cargue de las cuentas de cobro en el sistema <\\/span><b>SGAFT \\u2013 SAP<\\/b><span> para pago de los contratos <\\/span><span>en general d<\\/span><span>el 2026 con su respectiva verificación de firmas y documentos los cuales se relacionan en las carpeta compartida mes de JULIO cuota 1,<\\/span><span>&nbsp; <\\/span><span>contratación 2026, y se procede a subirlos a la ME23N sistema<\\/span><b> SGAFT \\u2013 SAP.<\\/b><span>&nbsp;<\\/span>\\n <\\/p>"},{"obligacion":"10. Atender las demás solicitudes y/o actividades que realice el (la) Director (a) del Departamento Administrativo de Gestión Jurídica Pública ó el supervisor relacionadas con el objeto del contrato.","actividad":"<p style=\\"text-align: justify;\\"><span>-&nbsp;<\\/span><span>En este periodo no se realizó esta actividad.<\\/span><b><span><span>&nbsp;<\\/span><\\/span><\\/b><\\/p>\\n<p style=\\"text-align: justify;\\"><span>-&nbsp;<\\/span><span>En el siguiente link se encontrará las evidencias ya relacionadas.<\\/span><\\/p>\\n<p style=\\"text-align: justify;\\"><span>https://drive.google.com/drive/folders/1QgVFyF5Qn89w69K4fpW5mVBx8L0FOjSs?usp=drive_link<\\/span><\\/p>"}]', 'https://drive.google.com/drive/folders/1j_LG4ObiR7c7rJfRdmZC_sRgqw62bwCd?usp=sharing', '0481', '{"evidencia_2_0":{"name":"1 . EVIDENCIAS CUOTA 6.docx","id":"1p7jwFNXP-e87CURpZRweRS9kLK2tKRZO","url":"https://drive.google.com/file/d/1p7jwFNXP-e87CURpZRweRS9kLK2tKRZO/view"},"evidencia_0_0":{"name":"1 . EVIDENCIAS CUOTA 6.docx","id":"1Yrislj5uLdXIqBeg3XYsU2jxWuPna6_j","url":"https://drive.google.com/file/d/1Yrislj5uLdXIqBeg3XYsU2jxWuPna6_j/view"},"evidencia_1_0":{"name":"1 . EVIDENCIAS CUOTA 6.docx","id":"1Y22KvLBcH_QRH91oM2eqOmlmuHFxmkZs","url":"https://drive.google.com/file/d/1Y22KvLBcH_QRH91oM2eqOmlmuHFxmkZs/view"},"file_rut":{"name":"7. RUT - ÓSCAR BETANCUR.p