INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (80, 2015, '2026-09', 'PARCIAL', '2', '2026-07-28', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 2109000.00, 1054500.00, 8436000.00, '09908932', '09908932', 'aportes en linea', '2026-09-03', '2026-08', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-01 14:31:39.823055', '2026-09-07', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar apoyo en la realización de las actividades de aseo y mantenimiento de las instalaciones fisicas del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p>Como consecuencia del terremoto ocurrido\\n<br>en Santiago de Cali y de la restricción\\n<br>temporal de acceso al Edificio del CAM, las\\n<br>actividades inicialmente previstas se vieron\\n<br>transitoriamente interrumpidas. Ante esta\\n<br>situación, las labores fueron reorientadas\\n<br>temporalmente para brindar apoyo al\\n<br>Departamento Administrativo de Gestión\\n<br>Jurídica Pública en el Coliseo del Pueblo,\\n<br>escenario habilitado como centro de acopio\\n<br>para la recepción de donaciones y como\\n<br>sede del Puesto de Mando Unificado\\n<br>(PMU), en el cual participó la Directora del\\n<br>Departamento Administrativo de Gestión\\n<br>Jurídica Pública.<\\/p><p>En desarrollo de este apoyo, la contratista\\n<br>colaboró en las labores de aseo y\\n<br>adecuación de los espacios dispuestos para\\n<br>el funcionamiento del centro de acopio y del\\n<br>Puesto de Mando Unificado (PMU).<br><\\/p>"},{"obligacion":"2. Brindar apoyo en la realización de las actividades de  aseo de la Oficina del Director(a).","actividad":"Brindar apoyo en las actividades de aseo,\\n<br>organización y adecuación de los espacios\\n<br>habilitados temporalmente para el\\n<br>funcionamiento del centro de acopio y del\\n<br>Puesto de Mando Unificado (PMU), con\\n<br>ocasión de la contingencia generada por el\\n<br>terremoto ocurrido en Santiago de Cali."},{"obligacion":"3. Brindar apoyo en a conservación y seguridad de los elementos suministrados para la ejecución de las actividades de servicios generales que le sean requeridas.","actividad":"Organizó y guardó todos los elementos que\\n<br>le fueron asignados en sus respectivos\\n<br>lugares de almacenamiento."},{"obligacion":"4. Brindar apoyo en las actividades de  limpieza y desinfección de la ornamentación del organismo.","actividad":"Realizó labores de limpieza de pisos."},{"obligacion":"5. Brindar apoyo en la preparación y  suministro de bebidas tales como agua, tinto y/o  aromáticas requeridas por los funcionarios, contratistas y usuarios externos e internos del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"Brindó apoyo en el suministró de bebidas,\\n<br>entre ellas agua, tinto, aromáticas, etc tanto\\n<br>a los funcionarios como a los contratistas\\n<br>ubicados en el Coliseo del Pueblo."},{"obligacion":"6. Atender las demás solicitudes y/o actividades que realice el (la) Director (a) del Departamento Administrativo de Gestión Jurídica Pública ó el supervisor relacionadas con el objeto del contrato.","actividad":"<p>Atendió los requerimientos que se le fueron\\n<br>impartidos por parte de la Directora del&nbsp;Departamento, brindando apoyo en\\n<br>actividades correspondientes a los servicios\\n<br>generales y de organización de las\\n<br>instalaciones, desarrollando de manera\\n<br>temporal sus actividades en el Coliseo del\\n<br>Pueblo.<\\/p>"}]', 'https://drive.google.com/drive/folders/1tBa-dwNi8aUBy7hZ8jjP4PUC7mRaAAMK?usp=sharing', '0635', '{"file_seguridad_social":{"name":"4. SEGURIDAD SOCIAL CUOTA 2 - ELIZABETH MURILLO.pdf","id":"1ydb0-b6SPewwjOUuhhb601QYY-RDTGav","url":"https://drive.google.com/file/d/1ydb0-b6SPewwjOUuhhb601QYY-RDTGav/view"},"file_rpc":{"name":"1. RPC - ELIZABETH MURILLO.pdf","id":"1EGyXbcFkF4z8UCtUg3JKt8fqBe59xNFx","url":"https://drive.google.com/file/d/1EGyXbcFkF4z8UCtUg3JKt8fqBe59xNFx/view"}}', 'APROBADA PARA IMPRESION', 14, NULL, '', '', 2026, '', '', '', 'NO', 314, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (81, 2005, '2026-08', 'PARCIAL', '2', '2026-07-08', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 3551000.00, 3551000.00, 14204000.00, '6027876749', '568646008', 'Soi', '2026-08-18', '2026-08', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-01 19:04:08.652682', '2026-08-26', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Apoyar a la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico del Departamento Administrativo de Gestión Jurídica Pública en las actuaciones y consulta, control y seguimiento del sistema de información documental, así como en las asignaciones dadas a los diferentes integrantes de los equipos de trabajo.","actividad":"Realizó la recepción, revisión y gestión de las comunicaciones oficiales recibidas a través del correo electrónico institucional y del sistema de gestión documental Orfeo, efectuando el reparto y asignación de los documentos a los profesionales responsables según su competencia, así como el seguimiento al trámite correspondiente."},{"obligacion":"2. Apoyo  para la elaboración del informe que consolide la información mensual relacionada con la valoración del contingente, de las conciliaciones prejudiciales, los procesos judiciales y laudos arbitrales registrados en el Sistema de Información de Procesos Judiciales del Departamento Administrativo de Gestión Jurídica Pública, que documente las cantidades de procesos calificados y pendientes por calificar.","actividad":"<p>Elaboró actas de calificación del contingente judicial como insumo para el informe mensual a la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico, a partir de la revisión de procesos judiciales en coordinación con el apoderado.<\\/p>\\n<p><br>\\n  Acta No. 4121.040.3.2.178 <br>\\n  Acta No. 4121.040.3.2.JOSE ZAMORA <br>\\n  Acta No. 4121.040.3.2.HECTOR MARIO<\\/p>"},{"obligacion":"3. Elaborar comunicaciones oficiales, actas y demás documentos que solicite el (la) Subdirector(a) de Defensa Judicial y Prevención del Daño Antijurídico.","actividad":"<p>Realizó la elaboración, redacción y trámite de oficios y comunicaciones oficiales, garantizando la adecuada estructuración documental, el cumplimiento de los lineamientos institucionales y su radicación y despacho a través del sistema de gestión documental Orfeo. <br><\\/p>\\n<p>Radicado No. <br>\\n  202641210400000874 <br>\\n  202641210400000241 <br>\\n  202641210400000884 <br>\\n  202641210400000894 <br>\\n  202641210400000904 <br>\\n  202641210400000914 <br>\\n  202641210400000251<\\/p>"},{"obligacion":"4. Apoyar en la revisión del pago de seguridad social de los contratistas que la supervisión del contrato esté a cargo  el (la) Subdirector(a) de Defensa Judicial y Prevención del Daño Antijurídico.","actividad":"Realizó la revisión y verificación de los soportes de pago de seguridad social presentados por los contratistas cuya supervisión se encontraba a cargo de la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico, comprobando el cumplimiento de los requisitos establecidos para el trámite correspondiente."},{"obligacion":"5.Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.","actividad":"<p>Realizó el despacho de las comunicaciones oficiales que firma la subdirectora de defensa judicial y prevención del daño antijurídico por el sistema de gestión documental Orfeo Radicó las comunicaciones oficiales y&nbsp;contestaciones de acciones de tutela con visto bueno de la subdirectora de defensa judicial y prevención del daño antijurídico para la firma de la directora del departamento administrativo de gestión jurídica pública.<\\/p>"}]', 'https://drive.google.com/drive/folders/1Kex2AFpS3CZucsiQ8IZcfEXFcLh3gdJ0?usp=sharing', '0618', '{"evidencia_3_0":{"name":"REVISION CUENTAS AGOSTO.pdf","id":"1CUgqbGg0pncHBKEk0QWsg6PPTXXtxN9Q","url":"https://drive.google.com/file/d/1CUgqbGg0pncHBKEk0QWsg6PPTXXtxN9Q/view"},"evidencia_2_0":{"name":"1202641210400000904_00001.pdf","id":"1Hom5UeR-aoRCeSUvaZ-_zJ7dVxKzJqdp","url":"https://drive.google.com/file/d/1Hom5UeR-aoRCeSUvaZ-_zJ7dVxKzJqdp/view"},"evidencia_0_0":{"name":"EVIDENCIA PUNTO 1 CUOTA 2.pdf","id":"1AQShjGy-6TSw8Y6EuCXVFJmg0cP1c3tL","url":"https://drive.google.com/file/d/1AQShjGy-6TSw8Y6EuCXVFJmg0cP1c3tL/view"},"evidencia_1_0":{"name":"ACTA - 178 - SANDRA MILENA ENRIQUEZ - JUL 27 2026.pdf","id":"1kiNqcUCf-EbRW31GVz8izAWZtX0BbjEy","url":"https://drive.google.com/file/d/1kiNqcUCf-EbRW31GVz8izAWZtX0BbjEy/view"},"evidencia_4_0":{"name":"Relacion orfeo (1).xlsx","id":"1IMyQ7JKoMsg5y32oh9A7C1TOfMeWnhsH","url":"https://drive.google.com/file/d/1IMyQ7JKoMsg5y32oh9A7C1TOfMeWnhsH/view"},"file_seguridad_social":{"name":"4. SEGURIDAD SOCIAL CUOTA 2 - ANGELICA RUANO.pdf","id":"1sFzPUQFVKuBopra8NJEPD-_GMz1Dqv8o","url":"https://drive.google.com/file/d/1sFzPUQFVKuBopra8NJEPD-_GMz1Dqv8o/view"},"evidencia_2_0_5":{"name":"1202641610500061944_00001.pdf","id":"1RODKQ2XvMN1iirnjVigP7CU1BZ-RIZvb","url":"https://drive.google.com/file/d/1RODKQ2XvMN1iirnjVigP7CU1BZ-RIZvb/view"},"evidencia_2_0_3":{"name":"1202641210400000241_00001.pdf","id":"1OzcW9SY8oIm7IRjY-z