INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (129, 1943, '2026-10', 'PARCIAL', '4', '2026-07-07', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 2271000.00, 6813000.00, 4542000.00, '1084658279', '1084658279', 'SIMPLE', '2026-09-25', '2026-09', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-07 14:57:10.039477', '2026-10-26', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Clasificar y archivar los diversos documentos que le sean encomendados, especialmente producto de la gestión de las cajas menores.","actividad":"<p align=\\"left\\">Brindo apoyo en la actividad de clasificar los diversos documentos de las carpetas físicas de caja menor Juri 1, Juri 2 y Juri 3<\\/p>"},{"obligacion":"2. Apoyar en el suministro de insumos de oficina y en la gestión del almacén del organismo.","actividad":"<p>Brindo apoyo en la recogida de insumos de oficina solicitados por el departamento administrativo de gestión jurídica publica&nbsp;<span>para su posterior reparto según las solicitudes de las distintos despachos&nbsp;<\\/span><\\/p>"},{"obligacion":"3. Apoyar en el seguimiento de los consumos de combustible del parque automotor del organismo.","actividad":"<p data-pm-slice=\\"1 1 []\\"><span>Apoyó en la recepción de los soportes relacionados con el consumo de combustible de los vehículos oficiales asignados al Departamento, realizando su respectiva clasificación y organización. Esta labor tuvo como propósito fortalecer el control documental y facilitar la conciliación de los registros con el área correspondiente de la Unidad Administrativa Especial de Gestión de Bienes y Servicios del Distrito. A continuación, se presenta la relación de los comprobantes suministrados por los conductores responsables de los vehículos oficiales durante el mes de OCTUBRE de 2026.<\\/span><\\/p><table style=\\"text-align: center;\\"><tbody><tr><td style=\\"text-align: center;\\">JOS18E<\\/td><td style=\\"text-align: center;\\">ONL301<\\/td><\\/tr><tr><td style=\\"text-align: center;\\">1126731<\\/td><td style=\\"text-align: center;\\">6270644<\\/td><\\/tr><tr><td style=\\"text-align: center;\\">1121202<\\/td><td style=\\"text-align: center;\\">8978525<\\/td><\\/tr><tr><td style=\\"text-align: center;\\"><br><\\/td><td style=\\"text-align: center;\\">8988766<\\/td><\\/tr><tr><td style=\\"text-align: center;\\"><br><\\/td><td style=\\"text-align: center;\\">8991305<\\/td><\\/tr><tr><td style=\\"text-align: center;\\"><br><\\/td><td style=\\"text-align: center;\\">8996397<\\/td><\\/tr><\\/tbody><\\/table><p data-pm-slice=\\"1 1 []\\" style=\\"text-align: center;\\"><span><br><\\/span><\\/p>"},{"obligacion":"4. Escanear documentos, tomar fotocopias, atender al público y realizar las actividades de apoyo al proceso que le sean requeridas","actividad":"<p>Brindo apoyo en el escaneo de los informes de supervisión de los contratistas que presentaron la cuenta de cobro del mes de octubre de 2026, relacionadas a continuación<\\/p><p><img src=\\"/combinacion/ImageServlet?id=1WQlSyfkHi1fFCFlcxeZ2lxp_kVz5xgiC\\" style=\\"width: 320px;\\"><br><\\/p>"},{"obligacion":"5. Atender las demás solicitudes que realice el (la) Director (a) del el Departamento Administrativo de Gestión Jurídica Pública y supervisor relacionadas con el objeto del contrato","actividad":"Para este periodo no se realizaron actividades asignadas por la Directora del Departamento"}]', 'https://drive.google.com/drive/folders/1lQuLexxhT39k5HZieHKcoP1AsfTctoCq?usp=sharing', '0724', '{"file_seguridad_social":{"name":"4. SEGURIDAD SOCIAL CUOTA 4 - PABLO CAMILO.pdf","id":"1nEle2bXQ9sa1M0dheZFiMFt8ZlHj2JCj","url":"https://drive.google.com/file/d/1nEle2bXQ9sa1M0dheZFiMFt8ZlHj2JCj/view"},"file_rpc":{"name":"1. RPC - PABLO CAMILO.pdf","id":"1vXfaMhFvVIymVGiKQZ0dGQf9tKLryplM","url":"https://drive.google.com/file/d/1vXfaMhFvVIymVGiKQZ0dGQf9tKLryplM/view"}}', 'APROBADA PARA IMPRESION', 14, NULL, '', '', 2026, '', '', '', 'NO', 315, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (132, 1978, '2026-08', 'PARCIAL', '2', '2026-07-09', '2026-10-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 6247000.00, 6247000.00, 12494000.00, '1083702440', '8823807442', 'Pago Simple', '2026-08-03', '2026-08', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-07 15:29:54.687849', '2026-08-26', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar apoyo profesional en la revisión de fichas técnicas, convocatorias y organización de las sesiones del Comité de Conciliación y Defensa Judicial.","actividad":"<span>\\n <p style=\\"\\">-a) Subió al drive y analizó los informes previos al comité de conciliación de los apoderados que presentaron casos para revisión de las sesiones número 47, 48, 49, 50 y 51.<\\/p>\\n <p style=\\"\\">-b) Organizó las sesiones número 47, 48, 49, 50 y 51 del Comité de Conciliación y Defensa Judicial.<\\/p><\\/span>"},{"obligacion":"2. Proyectar las actas de reunión de las sesiones ordinarias y extraordinarias que realice el Comité de Conciliación y Defensa Judicial del Distrito Especial de Santiago de Cali.","actividad":"<span>\\n <p style=\\"\\">-a) Proyectó las actas de reunión de las sesiones ordinarias número 47, 48, 50 y 51.<\\/p>\\n <p style=\\"\\">ACTA DE REUNIÓN 4121.040.1.047, ACTA DE REUNIÓN 4121.040.1.048, ACTA DE REUNIÓN 4121.040.1.050 y ACTA DE REUNIÓN 4121.040.1.051.<\\/p>\\n <p style=\\"\\">-b) Proyectó el acta de reunión de la sesión Extraordinaria número 49.<\\/p>\\n <p style=\\"\\">ACTA DE REUNIÓN 4121.040.1.049.<\\/p><\\/span>"},{"obligacion":"3. Proyectar las actas del Comité de Conciliación y Defensa Judicial del Distrito Especial de Santiago de Cali que deban presentar los apoderados judiciales dentro de las etapa prejudiciales y judiciales donde el Distrito Especial de Santiago de Cali se encuentre vinculado.","actividad":"<span>-a) Proyectó las pre-actas y actas de los comité de conciliación ordinario y extraordinarios número 359 hasta la 377 y actas comité del estudio de la posible acción de repetición número 053 hasta la 084.<\\/span>"},{"obligacion":"4.Proyectar los informes que el Comité de Conciliación y Defensa Judicial debe presentar al señor Alcalde del Distrito de Santiago de Cali y Órganos de Control.","actividad":"<span>\\n <p style=\\"\\">-a) Recopiló y consolidó la información de los casos analizados por el Comité de Conciliación y Defensa Judicial para la elaboración de los informes que debe presentar al señor Alcalde del Distrito de Santiago de Cali y Órganos de Control, como consta en el siguiente enlace:&nbsp;<\\/p>\\n <p style=\\"font-weight: bold;\\"><a href=\\"https://drive.google.com/drive/u/0/folders/1s-2wK2bvCgGMRB2_8GzbTtTSTGg73Zu3\\"><span>https://drive.google.com/drive/u/0/folders/1s-2wK2bvCgGMRB2_8GzbTtTSTGg73Zu3<\\/span><\\/a><\\/p><\\/span>"},{"obligacion":"5. Ejercer la representación judicial de acciones constitucionales de la Entidad que le sean asignado","actividad":"<span>\\n <p style=\\"\\">-a) Proyectó respuesta a acción de tutela de la señora Ana Beleny Ortega Hoyos Y Otros con radicado 760014189004-2026-01079-00.<\\/p>\\n <div style=\\"\\">\\n  <table>\\n   <colgroup>\\n    <col>\\n    <col>\\n    <col>\\n    <