INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (139, 2015, '2026-09', 'PARCIAL', '3', '2026-07-28', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 2109000.00, 3163500.00, 6327000.00, '9511470417', '9511470417', 'aportes en linea', '2026-09-22', '2026-09', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-08 08:56:54.213573', '2026-09-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar apoyo en la realización de las actividades de aseo y mantenimiento de las instalaciones fisicas del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"Realizó las labores de aseo en la cocina y\\n<br>en los espacios designados por el\\n<br>Departamento Administrativo de Gestión\\n<br>Jurídica Pública."},{"obligacion":"2. Brindar apoyo en la realización de las actividades de  aseo de la Oficina del Director(a).","actividad":"Realizó la limpieza del despacho del\\n<br>Departamento Administrativo de Gestión\\n<br>Jurídica Pública, así como el aseo del baño\\n<br>del mismo."},{"obligacion":"3. Brindar apoyo en a conservación y seguridad de los elementos suministrados para la ejecución de las actividades de servicios generales que le sean requeridas.","actividad":"Organizó y guardó todos los elementos que\\n<br>le fueron asignados en sus respectivos\\n<br>lugares de almacenamiento."},{"obligacion":"4. Brindar apoyo en las actividades de  limpieza y desinfección de la ornamentación del organismo.","actividad":"Realizó la limpieza de paredes y pisos, así\\n<br>como el vaciado de los cubos de basura\\n<br>correspondientes a cada uno de los puestos\\n<br>de trabajo asignados al Departamento\\n<br>Administrativo de Gestión Jurídica Pública."},{"obligacion":"5. Brindar apoyo en la preparación y  suministro de bebidas tales como agua, tinto y/o  aromáticas requeridas por los funcionarios, contratistas y usuarios externos e internos del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"Preparó y suministró tintos, aromáticas para\\n<br>las reuniones entre funcionarios y\\n<br>contratistas externos e internos de la\\n<br>Administración municipal Alcaldía de\\n<br>Santiago de Cali."},{"obligacion":"6. Atender las demás solicitudes y/o actividades que realice el (la) Director (a) del Departamento Administrativo de Gestión Jurídica Pública ó el supervisor relacionadas con el objeto del contrato.","actividad":"Atendió los requerimientos que se le fueron\\n<br>impartidos por parte de la directora del\\n<br>Departamento."}]', 'https://drive.google.com/drive/folders/1X4TL-XV1-5b_1C3FWYXfjXXcyFi2ufzq?usp=sharing', '0708', '{"file_seguridad_social":{"name":"4. SEGURIDAD SOCIAL CUOTA 3 - ELIZABETH MURILLO.pdf","id":"1mtbR2c78Mtw2rBp6NoGeylYTxgjuoFfS","url":"https://drive.google.com/file/d/1mtbR2c78Mtw2rBp6NoGeylYTxgjuoFfS/view"},"file_rpc":{"name":"1. RPC - ELIZABETH MURILLO.pdf","id":"18OuMwRel0tq_eME7bZ182Q1e2gp0gJxQ","url":"https://drive.google.com/file/d/18OuMwRel0tq_eME7bZ182Q1e2gp0gJxQ/view"}}', 'APROBADA PARA IMPRESION', 14, NULL, '', '', 2026, '', '', '', 'NO', 314, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (140, 1953, '2026-07', 'PARCIAL', '1', '2026-07-16', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 6247000.00, 0.00, 31235000.00, '1083792645', '498450478', 'SIMPLE', '2026-07-21', '2026-07', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-08 10:34:15.821812', '2026-07-29', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1.Apoyar en los asuntos administrativos y jurídicos del Director(a) del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p><span>El contratista realizó la coordinación y la actualización de\\nla carpeta de Drive correspondiente a la Estrategia de Rendición de Cuentas, el\\n16 de julio de 2026, incorporando y organizando las evidencias que soportan el\\ncumplimiento de las actividades ejecutadas de acuerdo con el cronograma\\nestablecido, con el fin de mantener la información actualizada y facilitar el\\nseguimiento y la verificación de los avances de la estrategia.<\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span>Drive:<\\/span><\\/p>\\n\\n<p><a href=\\"https://drive.google.com/file/d/1jMUXd9vOXs05FRi9EPUOZRfazzEwRm8J/view?usp=share_link\\"><span>https://drive.google.com/file/d/1jMUXd9vOXs05FRi9EPUOZRfazzEwRm8J/view?usp=share_link<\\/span><\\/a><span><\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>"},{"obligacion":"2. Atender  las diferentes auditorías realizadas por los Entes de Control y Control Interno.","actividad":"<p><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>El contratista coordino la revisión\\ny consolidación de las acciones de mejora suscritas en el Plan de Mejoramiento,\\nel 16 de julio de 2026, derivado de la Auditoría de Cumplimiento\\n\\"Evaluación de la Gestión del Distrito Especial de Santiago de Cali en las\\nDemandas y Litigios \\u2013 Vigencias 2022 y 2023\\", verificando la consistencia\\nde las acciones formuladas, los responsables, los plazos de ejecución y los\\nsoportes correspondientes, con el fin de fortalecer el seguimiento y cumplimiento\\nde los compromisos adquiridos con la Contraloría General de Santiago de Cali.<\\/span><b><span><\\/span><\\/b><\\/p>\\n\\n<p><b><span><span>&nbsp;<\\/span><\\/span><\\/b><\\/p>\\n\\n<p><span>Drive:<\\/span><\\/p>\\n\\n<p><a href=\\"https://docs.google.com/spreadsheets/d/1_Wk1tGgbyx-U7z4o4y1NCHMc_y_lUq-Y/edit?usp=share_link&amp;ouid=116561847718795045116&amp;rtpof=true&amp;sd=true\\"><span>https://docs.google.com/spreadsheets/d/1_Wk1tGgbyx-U7z4o4y1NCHMc_y_lUq-Y/edit?usp=share_link&amp;ouid=116561847718795045116&amp;rtpof=true&amp;sd=true<\\/span><\\/a><u><span><\\/span><\\/u><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>El contratista participó en la\\nreunión inicial IL_2026_7 Seguimiento Plan de Mejoramiento Archivístico 1er\\ntrimestre 2026, realizada el día<span>&nbsp; <\\/span>22 de\\njulio de 2026 en modalidad virtual. <\\/span><span><\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span>Drive:<\\/span><\\/p>\\n\\n<p><a href=\\"https://drive.google.com/file/d/1V2WRKGPQGJR3Wx9bY9OlfGi9W4jK4wPJ/view?usp=share_link\\"><span>https://drive.google.com/file/d/1V2WRKGPQGJR3Wx9bY9OlfGi9W4jK4wPJ/view?usp=share_link<\\/span><\\/a><span><\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>El contratista asistió a reunión de\\ncontacto inicial \\u2013 Ejercicio Auditor IL_2026_8 Informe de seguimiento a la\\natención de las Peticiones, Quejas, Reclamos, Sugerencias y Denuncias (PQRSD) \\u2013\\nPrimer Semestre de 2026, el día 23 de julio de 2026 en modalidad virtual.<\\/span><b><span><\\/span><\\/b><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span>Drive:<\\/span><\\/p>\\n\\n<p><a href=\\"https://drive.google.com/file/d/1nv3CIlvhrK4jNzivyWAnhtJmb2g0G9Cm/view?usp=share_link\\"><span>https://drive.google.com/file/d/1nv3CIlvhrK4jNzivyWAnhtJmb2g0G9Cm/view?usp=share_link<\\/span><\\/a><span><\\/span><\\/p>"},{"obligacion":"3. Brindar soporte en la formulación, elaboración y seguimiento de los planes de mejoramiento suscritos por el Departamento Administrativo de Gestión Jurídica Pública y de aquellos que formulen los organismos para consideracion del Alcalde.","actividad":"<p><span>El contratista realizó la solicitud de cargue en el\\naplicativo SIA Observa del &nbsp;avance&nbsp;del 100% del Plan de Mejoramiento,\\nproducto de la Auditoría de Cumplimiento sobre la evaluación de la gestión del\\nDistrito Especial de Santiago de Cali en materia de demandas y litigios,\\ncorrespondiente a las vigencias 2022 y 2023, suscrito con\\nla&nbsp;Contraloría&nbsp;General de Santiago de Cali, con corte 30 de junio de\\n2026.<\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span>Drive:<\\/span><\\/p>\\n\\n<p><a href=\\"https://drive.google.com/file/d/1oyhz-OMMP0HB9NlQmM6Dn_7XjpyZTrQy/view?usp=share_link\\"><span>https://drive.google.com/file/d/1oyhz-OMMP0HB9NlQmM6Dn_7XjpyZTrQy/view?usp=share_link<\\/span><\\/a><span><\\/span><\\/p>"},{"obligacion":"4. Brindar soporte en la consolidación de los informes de gestión del organismo","actividad":"<p><b><span><span>&nbsp;<\\/span><\\/span><\\/b><\\/p>\\n\\n<p><span>En el presente periodo no se requirió la ejecución de\\nactividades relacionadas.<b><\\/b><\\/span><\\/p>"},{"obligacion":"5. Brindar soporte en la formulación, elaboración, sustentación, ejecución, seguimiento y ajustes al Plan Operativo Anual de Inversiones POAI utilizando la Metodología General Aplicada (MGA), siguiendo los lineamientos del DAPM y aplicando criterios jurídicos \\u2013 administrativos para su elaboración","actividad":"<p><b><span><span>&nbsp;<\\/span><\\/span><\\/b><\\/p>\\n\\n<p><span>En el presente periodo no se requirió la ejecución de\\nactividades relacionadas.<b><\\/b><\\/span><\\/p>"},{"obligacion":"6. Brindar soporte en la implementación y sostenimiento del Modelo Integrado de Planeación y Gestión (MIPG), del modelo estándar de control interno (MECI) siguiendo los procedimientos establecidos.","actividad":"<p><span>El contratista coordinó reunión con el equipo de calidad del DAGJP para\\nla revisión del plan de trabajo del macroproceso de gestión jurídico\\nadministrativa conforme a las acciones correspondientes al Modelo Integrado de\\nPlaneación y Gestión MIPG. La reunión se realizó el día 22 de julio de 2026 en\\nmodalidad virtual.<\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span>Drive:<\\/span><\\/p>\\n\\n<p><a href=\\"https://drive.google.com/file/d/1FfERTecRNZxDuocddOHL3hT7ciwGPn5t/view?usp=share_link\\"><span>https://drive.google.com/file/d/1FfERTecRNZxDuocddOHL3hT7ciwGPn5t/view?usp=share_link<\\/span><\\/a><span><\\/span><\\/p>"},{"obligacion":"7.  Revisar y proyectar actos administrativos y atender derechos de petición que le sean asignados.","actividad":"<p><span>En el presente periodo no se requirió la ejecución de\\nactividades relacionadas.<b><\\/b><\\/span><\\/p>"},{"obligacion":"8. Apoyar las diferentes etapas de la contratacion del organismo, cuando sea requerido.","actividad":"<p><span>En el presente periodo no se requirió la ejecución de\\nactividades relacionadas.<b><\\/b><\\/span><\\/p>"},{"obligacion":"9. Realizar el apoyo de la supervisión de los contratos asignados por el Director del Departamento Administrativo de Gestión Jurídica.","actividad":"<p><span>En el presente periodo no se requirió la ejecución de\\nactividades relacionadas.<b><\\/b><\\/span><\\/p>"},{"obligacion":"10. Atender las demás solicitudes y/o actividades que realice el (la) Director (a) del Departamento Administrativo de Gestión Jurídica Pública ó el supervisor relacionadas con el objeto del contrato.","actividad":"<span>El contratista atendió las solicitudes del\\nDirector(a) del Departamento Administrativo de Gestión Jurídica Pública según\\nrequerimientos realizados por correo electrónico<\\/span>"}]', 'https://drive.google.com/drive/folders/1FzXUoNilPZ5mR4sqxxQoeo0x300QESJh?usp=sharing', '0492', E'{"evidencia_2_0":{"name":"Solicitud de reporte del avance (100%) del Plan de Mejoramiento \\u2013 Demandas y Litigios \\u2013 SI.pdf","id":"1iohLkGFpHz0rdrJFdSI9_xZE8OZhu1k_","url":"https://drive.google.com/file/d/1iohLkGFpHz0rdrJFdSI9_xZE8OZhu1k_/view"},"evidencia_1_0":{"name":"Correo de Alcaldía de Cali - Invitación_ Citación a reunión de contacto inicial - Ejercici.pdf","id":"1Q0WTEYkm6_t3egpbA-q3a7mljWWaIEB0","url":"https://drive.google.com/file/d/1Q0WTEYkm6_t3egpbA-q3a7mljWWaIEB0/view"},"file_rut":{"name":"7. RUT - EMMANUEL ALJURE.pdf","id":"1caRULpIKC7pLGlsiy0nkPkpVsTCfBgFt","url":"https://drive.google.com/file/d/1caRULpIKC7pLGlsiy0nkPkpVsTCfBgFt/view"},"evidencia_5_0":{"name":"Avance Corte 30 junio 2026.xlsx","id":"1quawrMF6PuiLyGl7KW-GNQx8YOFv-d58","url":"https://drive.google.com/file/d/1quawrMF6PuiLyGl7KW-GNQx8YOFv-d58/view"},"file_secop":{"name":"2. CONTRATO SECOP II - EMMANUEL ALJURE.pdf","id":"1Wfo_1Fy6wNyig6n8Js5orLNdFtVyp1eV","url":"https://drive.google.com/file/d/1Wfo_1Fy6wNyig6n8Js5orLNdFtVyp1eV/view"},"file_cedula":{"name":"6. CEDULA - EMMANUEL ALJURE.pdf","id":"1XdgO7b0USAzJj9t3T2BOrSNIETNLxFCG","url":"https://drive.google.com/file/d/1XdgO7b0USAzJj9t3T2BOrSNIETNLxFCG/view"},"file_seguridad_social":{"name":"8. SEGURIDAD SOCIAL CUOTA 1 - EMMANUEL ALJURE.pdf","id":"1_2FQv5OFEZq2P7xC1JLzV0vWAxqDmBPb","url":"https://drive.google.com/file/d/1_2FQv5OFEZq2P7xC1JLzV0vWAxqDmBPb/view"},"file_ficha_tecnica":{"name":"4. FICHA TECNICA - EMMANUEL ALJURE.pdf","id":"17vH2eAV-K4z78fsd393KK4rjnffpCdG1","url":"https://drive.google.com/file/d/17vH2eAV-K4z78fsd393KK4rjnffpCdG1/view"},"file_rpc":{"name":"1. RPC - EMMANUEL ALJURE.pdf","id":"1wMURGi7CDZGi74eZJcl-VhQ5nK00Oepy","url":"https://drive.google.com/file/d/1wMURGi7CDZGi74eZJcl-VhQ5nK00Oepy/view"}}', 'APROBADA PARA IMPRESION', 14, NULL, '', '', 2026, '', '', '', 'NO', 315, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (141, 1979, '2026-07', 'PARCIAL', '1', '2026-07-10', '2026-10-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 5663000.00, 0.00, 16989000.00, '1082467259', '1082467259', 'Pago simple', '2026-07-11', '2026-07', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-08 11:08:39.295005', '2026-07-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Ejercer la representación judicial, extrajudicial y de acciones constitucionales de la Entidad que le sean asignados, cumpliendo oportunamente las actuaciones administrativas judiciales y extrajudiciales, asistiendo a las diligencias programadas, agotando los recursos que procedan,  reportando oportunamente las fechas de las diligencias programadas en audiencias virtuales o en estrados judiciales, sustentando ante el Comité de Conciliación y Defensa Judicial la estrategia de defensa de los procesos judiciales que le sean asignados y  de las actuaciones judiciales que requieran de posición institucional o que impliquen disposición del derecho en litigio. Todo lo anterior conforme a las normas legales vigentes y a los protocolos, instructivos o lineamientos establecidos por el Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<div style=\\"text-align: justify;\\"><span>Ejerció la representación judicial en los&nbsp;procesos asignados.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>-.Proceso: Restitución de Tierras.&nbsp;Radicado: 2023-00048. ID 152159&nbsp;Solicitante: Arelix Rivera Henao.&nbsp;Despacho: Juzgado Primero Civil del&nbsp;Circuito Especializado en restitución de&nbsp;Tierras Barrancabermeja-Santander.&nbsp;Actuación: Mediante Oficio radicado<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100023311 del 17 de julio, dio&nbsp;respuesta al Despacho.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>-Proceso: Restitución de Tierras.&nbsp;Radicado: 2026-00104. ID 155155.&nbsp;Solicitante: Pedro Luis Astudillo Ruiz y<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Lilia Bojorge Villano.Despacho: Juzgado Segundo Civil del Circuito Especializado en Restitución de&nbsp;Tierras de Santiago de Cali. Actuación: Mediante oficios radicados<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048584,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048664,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048714,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048724,20264121010002<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>33361, del 17 de julio de 2026, dirigidos a<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Planeación, Hacienda Secretaria de<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Vivienda Social y Habitat, Educación,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Policía Metropolitana, solicito atender<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>requerimiento del Despacho.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>-Proceso: Verbal de Pertenencia.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Radicado: 2026-00303. ID 151019<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Demandante: Diego Longa<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Demandado: Mercy Espinosa de Duque,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>personas inciertas e indeterminadas.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Despacho: Juzgado Veinte Civil<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Municipal.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Actuación: Mediante oficio radicado<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100023301 del 17 de julio<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>2026, dio respuesta al Despacho<\\/span><\\/div>"},{"obligacion":"2. Mantener actualizado el sistema de información de registro, control y seguimiento de procesos judiciales, relacionando la actividad desplegada en cada uno de los procesos a su cargo, realizando el cálculo de la provisión contable y la calificación del riesgo procesal en aquellos asuntos judiciales y conciliaciones extrajudiciales asignados. Lo anterior, a efectos de conformar el expediente físico o virtual y mantener la integridad y precisión en el proceso contable","actividad":"<div style=\\"text-align: justify;\\"><span>Mantuvo actualizado el Sistema de&nbsp;<\\/span><span>información, registro, control y<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>seguimientos de los siguientes procesos:<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Proceso: Restitución de Tierras.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Radicado: 2023-00048. ID 152159<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Solicitante: Arelix Rivera Henao.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Despacho: Juzgado Primero Civil del<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Circuito Especializado en restitución de<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Tierras Barrancabermeja-Santander.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Actuación: Mediante Oficio radicado<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100023311 del 17 de julio, dio<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>respuesta al Despacho.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>-Proceso: Restitución de Tierras.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Radicado: 2026-00104. ID 155155.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Solicitante: Pedro Luis Astudillo Ruiz y<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Lilia Bojorge Villano.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Despacho: Juzgado Segundo Civil del<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Circuito Especializado en Restitución de<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Tierras de Santiago de Cali.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Actuación: Mediante oficios radicados<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048584,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048664,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048714,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100048724,20264121010002<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>33361, del 17 de julio de 2026, dirigidos a<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Planeación, Hacienda Secretaria de<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Vivienda Social y Habitat, Educación,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Policía Metropolitana, solicito atender<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>requerimiento del Despacho.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>-Proceso: Verbal de Pertenencia.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Radicado: 2026-00303. ID 151019<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Demandante: Diego Longa<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Demandado: Mercy Espinosa de Duque,<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>personas inciertas e indeterminadas.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Despacho: Juzgado Veinte Civil<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Municipal.<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>Actuación: Mediante oficio radicado<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>202641210100023301 del 17 de julio<\\/span><\\/div><div style=\\"text-align: justify;\\"><span>2026, dio respuesta al Despacho<\\/span><\\/div>"},{"obligacion":"3.    Atender las diligencias administrativas, judiciales y extrajudiciales programadas dentro de los 45 días calendarios siguientes al vencimiento del plazo del contrato, correspondientes a los procesos asignados salvo que se presente una causal de inhabilidad o incompatibilidad sobreviniente.","actividad":"<div style=\\"text-align: justify;\\"><span>Esta obligación se hace exigible después&nbsp;de la terminación del contrato, en caso&nbsp;que se programen diligencias&nbsp;administrativas, judiciales y&nbsp;extrajudiciales dentro de los 45 días&nbsp;calendarios siguientes al vencimiento del&nbsp;<\\/span><span>plazo del contrato.<\\/span><\\/div>"},{"obligacion":"4.  Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual. \\nParágrafo. La representación judicial ejercida por el contratista corresponde a una actividad liberal que continúa ejerciendo este en cualquier escenario público o privado durante la ejecución del contrato sin exclusividad o subordinación alguna respecto al Distrito Especial de Santiago de Cali. No obstante, lo anterior, deberá dar cumplimento a las disposiciones consagradas en la Ley 1123 de 2007 (Código Disciplinario del Abogado) en lo que corresponde a deberes e incompatibilidades, especialmente la prohibición de litigio contra la entidad contratante.","actividad":"En este mes, no me han sido asignadas&nbsp;actividades relacionadas con el objeto&nbsp;contractual"}]', 'https://drive.google.com/drive/folders/1w9PhO2_NAARLZz-NKd6wYUqu52L8NEzJ?usp=sharing', '0518', '{"evidencia_0_0":{"name":"A Comandante de la Policia.pdf","id":"1Zs2d6itRImepPL8diSl-_mWuTqMr7_rt","url":"https://drive.google.com/file/d/1Zs2d6itRImepPL8diSl-_mWuTqMr7_rt/view"},"file_rut":{"name":"7. RUT - MARÍA ARIAS.pdf","id":"1v2yrORLCd5GFpB43gJH7xct5BfBAy--7","url":"https://drive.google.com/file/d/1v2yrORLCd5GFpB43gJH7xct5BfBAy--7/view"},"file_secop":{"name":"2. CONTRATO SECOP II - MARÍA ARIAS.pdf","id":"1TLrDlrOUtC9PH8a_97-Vao1vuYBovENL","url":"https://drive.google.com/file/d/1TLrDlrOUtC9PH8a_97-Vao1vuYBovENL/view"},"evidencia_0_0_1":{"name":"ARELIX RIVERA HENAO.pdf","id":"19FYdY4iD_Q0j8iczDURP0UgSAAuRMWlK","url":"https://drive.google.com/file/d/19FYdY4iD_Q0j8iczDURP0UgSAAuRMWlK/view"},"evidencia_0_0_2":{"name":"Caso Diego Longa .pdf","id":"1RY3JjLRCDRPiboiyp2C3HIzXjiugm3Tf","url":"https://drive.google.com/file/d/1RY3JjLRCDRPiboiyp2C3HIzXjiugm3Tf/view"},"file_seguridad_social":{"name":"8. SEGURIDAD SOCIAL CUOTA 1 - MARÍA ARIAS.pdf","id":"1IVmTpOE_cyY2bvMJ4ViRFSVagys0yQgO","url":"https://drive.google.com/file/d/1IVmTpOE_cyY2bvMJ4ViRFSVagys0yQgO/view"},"evidencia_0_0_5":{"name":"Pedro Luis Astudillo.pdf","id":"1ZKOpwFchuk0deCe7UoWAzazVnE6gAPyP","url":"https://drive.google.com/file/d/1ZKOpwFchuk0deCe7UoWAzazVnE6gAPyP/view"},"evidencia_0_0_6":{"name":"Secretaria de Educación.pdf","id":"1fmwd6rJEqveWj_TVLcIhpxdlYmOXkb1M","url":"https://drive.google.com/file/d/1fmwd6rJEqveWj_TVLcIhpxdlYmOXkb1M/view"},"evidencia_0_0_3":{"name":"Director de Hacienda.pdf","id":"1YExTGedFg79oMEGVIvc6uTC5asBYzz5d","url":"https://drive.google.com/file/d/1YExTGedFg79oMEGVIvc6uTC5asBYzz5d/view"},"evidencia_0_0_4":{"name":"Pedro Luis Astudillo Ruiz.pdf","id":"1ckNescYs2-kqyRqWsFYe4vSaKRMp2D-b","url":"https://drive.google.com/file/d/1ckNescYs2-kqyRqWsFYe4vSaKRMp2D-b/view"},"file_rpc":{"name":"1. RPC - MARÍA ARIAS.pdf","id":"1ySjeRyudZ2VSWqTeqqqI-sVO52TmZAYw","url":"https://drive.google.com/file/d/1ySjeRyudZ2VSWqTeqqqI-sVO52TmZAYw/view"},"file_cedula":{"name":"6. CEDULA - MARÍA ARIAS.pdf","id":"1_i0IFwmDGscBDscCGtqkBx5VBH7b9Gfr","url":"https://drive.google.com/file/d/1_i0IFwmDGscBDscCGtqkBx5VBH7b9Gfr/view"},"file_ficha_tecnica":{"name":"4. FICHA TECNICA - MARÍA ARIAS.pdf","id":"16fdqKvdGh75eHKfEONuNy5xffk6bn5ec","url":"https://drive.google.com/file/d/16fdqKvdGh75eHKfEONuNy5xffk6bn5ec/view"}}', 'APROBADA PARA IMPRESION', 12, NULL, '', '', 2026, NULL, NULL, NULL, 'NO', 318, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (142, 1939, '2026-07', 'PARCIAL', '1', '2026-07-03', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 6247000.00, 0.00, 31235000.00, '1082845209', '1082845209', 'simple', '2026-07-22', '2026-06', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-08 12:22:32.002153', '2026-07-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar apoyo en la ejecución de las actividades asignadas al gestor de compras del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\"><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>De acuerdo con la proyección de contratación prestación de servicios\\nenviada por la profesional María Eugenia González, se diligenció la Matriz de\\ncontratación con la cual se elaboran los documentos precontractuales y\\ncontractuales a suscribir en el mes de<span>&nbsp;\\n<\\/span>julio 2026, específicamente en los siguientes campos: Número de CDP,\\nFecha del CDP, Valor del CDP, Fecha de vencimiento del CDP, Apropiación\\npresupuestal, valor total del contrato, valor de honorarios y los nombres de\\nlos estructuradores de los procesos contractuales de prestación de servicios\\nprofesionales y apoyo a la gestión.<span>&nbsp; <\\/span><\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><a href=\\"https://docs.google.com/spreadsheets/d/1y94sMDYKMtDrEEDev2JE7rJFC5AZVHAt/edit?gid=1591922465#gid=1591922465\\"><span>MATRIZ PRESTADORES DE SERVICIOS 2026.xlsx\\n- Hojas de cálculo de Google<\\/span><\\/a><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>El contratista brindó apoyo a la\\nlíder del proceso de contratación en la recepción, revisión (presupuesto e\\ninsuficiencia) y organización de las hojas de vida de las personas que ingresan\\nen reemplazo de los contratistas salientes, con el fin de facilitar el\\ndesarrollo oportuno del proceso de contratación. <\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<div>\\n\\n<table border=\\"1\\" cellspacing=\\"0\\" cellpadding=\\"0\\" width=\\"274\\" style=\\"text-align: justify;\\">\\n <tbody><tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>RICARDO ANTONIO TELLEZ BAUTISTA<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n <tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>NESTOR RAUL BALANTA OREJUELA<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n <tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>BEATRIZ EUGENIA BONILLA MACHADO<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n <tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>ALVARO JIMENEZ FERNANDEZ<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n <tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>MARIA ANDREA LEMOS BALCAZAR<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n <tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>CARLOS HERNAN ORTIZ RAMIREZ<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n <tr>\\n  <td width=\\"274\\" valign=\\"top\\">\\n  <p><span>JORGE IVAN VILLAQUIRAN ARIAS<\\/span><\\/p>\\n  <\\/td>\\n <\\/tr>\\n<\\/tbody><\\/table>\\n\\n<\\/div>\\n\\n<p style=\\"text-align: justify;\\"><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>El contratista contactó y envió\\ncorreo electrónico a las personas que iniciarán el proceso de contratación para\\nel segundo semestre con el organismo, brindando la información y el\\nacompañamiento requeridos para su vinculación con el organismo. Personas que se\\nmencionan en el párrafo anterior.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>●&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><span>El contratista proyectó y envió\\ncorreo electrónico dirigido a la profesional de presupuesto del organismo,\\nsolicitando la elaboración del RPC del Contrato No. 4121.010.26.1.142 persona\\njurídica celebrado en el mes de julio de 2026 por el <\\/span><span>DAGJP.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>●&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><span>El contratista proyectó y envió\\ncorreos electrónicos dirigidos a la profesional de presupuesto del organismo,\\nsolicitando la elaboración de los RPC de los contratos celebrados en el mes de\\njulio de 2026 por el <\\/span><span>DAGJP.<\\/span><a href=\\"https://drive.google.com/drive/folders/1pTkhe-zp3L_Btafhgrssk39ErJltgf_f?usp=drive_link\\" style=\\"background-color: rgb(255, 255, 255);  font-weight: 400;\\"><span>https://drive.google.com/drive/folders/1pTkhe-zp3L_Btafhgrssk39ErJltgf_f?usp=drive_link<\\/span><\\/a><\\/p><p style=\\"text-align: justify;\\"><span>●&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><span>El contratista realizó la creación y el ajuste\\nde los flujos de aprobación en la plataforma SECOP II, con el fin de garantizar\\nel inicio de los procesos de contratación correspondientes al segundo semestre\\ndel Departamento Administrativo de Gestión Jurídica Pública.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>●&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><span>El contratista consolidó y\\norganizó la información remitida por la Subdirección de Defensa Judicial y\\nPrevención del Daño Antijurídico y la Subdirección de Doctrina y Asuntos\\nNormativos en la matriz de contratación administrada por el Grupo de Contratación,\\ncorrespondiente a los contratistas que continúan con el organismo, con el fin\\nde mantener actualizada la información y facilitar el nuevo trámite de\\ncontratación para el mes de julio 2026.<\\/span><\\/p><p>\\n\\n\\n\\n<span> <b><\\/b><\\/span><\\/p>"},{"obligacion":"2. Elaborar Fichas Técnicas Contables de los contratos de prestación de servicios celebrados por el DAGJP y adelantas las tareas  del trámite ante el Departamento Administrativo de Hacienda, de las fichas técnicas cotables que correspondan a contratos celebrados con personas jurídicas.","actividad":"<p><span><span>●<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>El contratista apoyo en la elaboración de las\\nfichas técnicas <span>en el aplicativo de Gestión de\\nContratistas <\\/span><\\/span><a href=\\"https://aplicaciones2.cali.gov.co/gestionContractual/login.php\\"><span>https://aplicaciones2.cali.gov.co/gestionContractual/login.php<\\/span><\\/a><span> <span>de los contratos de prestación de servicios\\npersona natural celebrados por el DAGJP en el mes de julio 2026<\\/span>, de los\\nsiguientes contratos:<\\/span><\\/p><div>\\n\\n<table border=\\"0\\" cellspacing=\\"0\\" cellpadding=\\"0\\" width=\\"622\\">\\n <tbody><tr>\\n  <td width=\\"133\\">\\n  <p><span>4121.010.26.1.088<\\/span><\\/p>\\n  <\\/td>\\n  <td width=\\"175\\">\\n  <p><span>VIVIANA PATRICIA VALENCIA TRIVIÑO<\\/span><\\/p>\\n  <\\/td>\\n  <td width=\\"11\\" valign=\\"bottom\\">\\n  <p><span>&nbsp;<\\/span><\\/p>\\n  <\\/td>\\n  <td width=\\"122\\">\\n  <p><span>4121.010.26.1.101<\\/spa