INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (265, 1973, '2026-10', 'PARCIAL', '4', '2026-07-07', '2026-12-30', E'Modificación No. 001 del 20 de octubre de 2026 mediante la cual las partes acordaron: PRORROGAR el Contrato de Prestación de servicios profesionales No. 4121.010.26.1.121-2026 hasta el 30 de diciembre de 2026; y ADICIONAR el Contrato de Prestación de servicios profesionales No. 4121.010.26.1.121-2026 por la suma de ONCE MILLONES TRESCIENTOS VEINTISEIS MIL PESOS M/CTE ($11.326.000). Dicha adición se pagará en dos (2) cuotas iguales, cada una de ellas por valor de cinco millones seiscientos sesenta y tres mil pesos m/cte ($5.663.000).\r\n\r\nPor lo tanto, el valor total del contrato queda en la suma de TREINTA Y TRES MILLONES NOVECIENTOS SETENTA Y OCHO MIL PESOS M/CTE ($33.978.000).', 'N/A', 'N/A', 'N/A', 'N/A', 5663000.00, 16989000.00, 11326000.00, '1085163537', '1085163537', 'SIMPLE S.A', '2026-10-22', '2026-10', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-14 18:02:43.956591', '2026-10-26', 'Mediante Modificación No. 001 del 20 de octubre de 2026 se adiciona la suma ONCE MILLONES TRESCIENTOS VEINTISEIS MIL PESOS M/CTE ($11.326.000).', 'Mediante Modificación No. 001 del 20 de octubre de 2026 se prorroga el Contrato de Prestación de servicios profesionales 4121.010.26.1.121-2026 hasta el 30 de diciembre de 2026.', 'N/A', 'N/A', E'[{"obligacion":"1.Apoyar en la remisión oportuna a los organismos de la Administración Central Distrital, según su competencia misional, de las acciones constitucionales que sean notificadas por los diferentes despachos judiciales, y en donde el Distrito Especial de Santiago de Cali se encuentre vinculado.","actividad":"<p><span>Apoyó en la remisión\\noportuna de 4292 acciones de tutela a los diferentes organismos de la Administración\\nCentral.<\\/span><\\/p>"},{"obligacion":"2. Informar oportunamente sobre la relevancia o impacto de acciones de tutela, sentencias y trámites de desacato, al Director, al Subdirector de Defensa Judicial y de Prevención del Daño Antijurídico y/o al supervisor del Contrato, para que se adopten las decisiones sobre el ejercicio de Defensa Judicial de la Entidad.","actividad":"<p>Informó oportunamente sobre la relevancia o impacto de 4292 acciones\\nde tutela, <span>&nbsp;<\\/span>al Subdirector de Defensa\\nJudicial y de Prevención del Daño Antijurídico y/o al supervisor del Contrato,\\npara que se adopten las decisiones sobre el ejercicio de Defensa.<\\/p>\\n\\n<p><span>&nbsp;<\\/span><\\/p>"},{"obligacion":"4. Apoyar en la asignación de acciones constitucionales a los apoderados del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p>Apoyó en la asignación de veintisiete (27) acciones\\nconstitucionales a los apoderados del Departamento Administrativo de Gestión\\nJurídica Pública.<\\/p>"},{"obligacion":"5. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.","actividad":"<p>Remitió de forma oportuna la contestación de diecinueve (19)\\nacciones de tutela a los correos de los despachos judiciales.<\\/p>"}]', 'https://drive.google.com/drive/folders/1LeGvmzn05VTEDXcGS65hREKj9QSwczhb?usp=sharing', '0753', '{"evidencia_3_0":{"name":"RADICACION CONTESTACIONES.docx","id":"1R8tOMlCAT8YisX-aRdULrIOUqe9SFcpQ","url":"https://drive.google.com/file/d/1R8tOMlCAT8YisX-aRdULrIOUqe9SFcpQ/view"},"evidencia_2_0":{"name":"REPARTO JCA.pdf","id":"1KhrhGEc71R2VWZ27wkRjYCC1XubCM2yp","url":"https://drive.google.com/file/d/1KhrhGEc71R2VWZ27wkRjYCC1XubCM2yp/view"},"evidencia_0_0":{"name":"EVIDENCIAS CUOTA CUATRO OCT 2026.docx","id":"1b4Im_dbOvdA8_bdSFwpgXE_e8h24e8uU","url":"https://drive.google.com/file/d/1b4Im_dbOvdA8_bdSFwpgXE_e8h24e8uU/view"},"evidencia_1_0":{"name":"EVIDENCIAS CUOTA CUATRO OCT 2026.docx","id":"1cpzmsl1cxO4Dq6Ms_ndmidKmLX1e8HfV","url":"https://drive.google.com/file/d/1cpzmsl1cxO4Dq6Ms_ndmidKmLX1e8HfV/view"},"file_rut":{"name":"8. RUT - KAREN ESCOBAR.pdf","id":"1vkplnsaTxlrIlxpDUCB0gSxfZ3fHVJbv","url":"https://drive.google.com/file/d/1vkplnsaTxlrIlxpDUCB0gSxfZ3fHVJbv/view"},"file_paz_salvo_orfeo":{"name":"Paz y salvo orfeo Cuota No. 4.pdf","id":"1bO4nZpj_hxaM2ko3DlxPG_36hwU6Il8w","url":"https://drive.google.com/file/d/1bO4nZpj_hxaM2ko3DlxPG_36hwU6Il8w/view"},"file_secop":{"name":"3. CONTRATO Y PANTALLAZO SECOP - KAREN ESCOBAR.pdf","id":"1Ct_fo9kKizC8zB_usGntU3gz-fZR7fG_","url":"https://drive.google.com/file/d/1Ct_fo9kKizC8zB_usGntU3gz-fZR7fG_/view"},"file_cedula":{"name":"7. CEDULA - KAREN ESCOBAR.pdf","id":"1rEcqb-X0Z_ub5TFCykFiUwJKIhjWMil-","url":"https://drive.google.com/file/d/1rEcqb-X0Z_ub5TFCykFiUwJKIhjWMil-/view"},"file_seguridad_social":{"name":"9. SEGURIDAD SOCIAL CUOTA 4 - KAREN ESCOBAR.pdf","id":"1eNp9rI3fA6qeu8Os_DqewqZvlSEzsdlm","url":"https://drive.google.com/file/d/1eNp9rI3fA6qeu8Os_DqewqZvlSEzsdlm/view"},"file_certificado_dependientes":{"name":"12. CERTIFICADO DEPENDIENTES - KAREN ESCOBAR.pdf","id":"12VUmKFg_K6Px_cJQgWyvD2_3yyoN99o9","url":"https://drive.google.com/file/d/12VUmKFg_K6Px_cJQgWyvD2_3yyoN99o9/view"},"file_modificacion":{"name":"2. OTROSI - KAREN ESCOBAR.pdf","id":"1BcZEjWSZ8Aj5Z3CqhklbXXH1Tfy2ERJi","url":"https://drive.google.com/file/d/1BcZEjWSZ8Aj5Z3CqhklbXXH1Tfy2ERJi/view"},"file_rpc":{"name":"1. RPC - KAREN ESCOBAR.pdf","id":"1yNCl8zo2mjhwTHlAXN4c0tAL2PsNa0JL","url":"https://drive.google.com/file/d/1yNCl8zo2mjhwTHlAXN4c0tAL2PsNa0JL/view"}}', 'APROBADA PARA IMPRESION', 89, NULL, '', '', 2026, '', '', '', 'NO', 321, NULL, NULL);
INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (266, 1981, '2026-07', 'PARCIAL', '1', '2026-07-25', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 5663000.00, 0.00, 28315000.00, '1083886552', '1083886552', 'SIMPLE', '2026-07-25', '2026-07', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-14 20:13:47.637572', '2026-08-26', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1.        Brindar apoyo en el control y seguimiento del cumplimiento de las sentencias de las acciones Constitucionales en las que el Distrito Especial de Santiago de Cali sea parte o se encuentre vinculado. Crear o Consolidar una herramienta de seguimiento y control de las acciones constituciones activas y mantenerla actualizada en tiempo real.","actividad":"<p><span>-Brindó apoyo en el control y seguimiento en las\\nsentencias de las acciones constitucionales en que el Distrito de Santiago de\\nCali es parte.<\\/span><\\/p>"},{"obligacion":"2.        Ejercer la representación judicial, extrajudicial en las acciones constitucionales en las que la Entidad sea parte o se encuentre vinculada,  que le sean asignados, cumpliendo oportunamente las actuaciones administrativas judiciales y extrajudiciales, asistiendo a las diligencias programadas, agotando los recursos que procedan, reportando oportunamente las fechas de las diligencias programadas en audiencias virtuales o en estrados judiciales, sustentando ante el Comité de Conciliación y Defensa Judicial la estrategia de defensa de los procesos judiciales que le sean asignados y de las actuaciones judiciales que requieran de posición institucional o que impliquen disposición del derecho en litigio. Todo lo anterior conforme a las normas legales vigentes y a los protocolos, instructivos o lineamientos establecidos por el Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<span>No se requirió esta\\nactividad para este periodo.<\\/span>"},{"obligacion":"3.        Mantener actualizado el sistema de información de registro, control y seguimiento de procesos judiciales, relacionando la actividad desplegada en cada uno de los procesos a su cargo, realizando el cálculo de la provisión contable y la calificación del riesgo procesal en aquellos asuntos judiciales y conciliaciones extrajudiciales asignados. Lo anterior, a efectos de conformar el expediente físico o virtual y mantener la integridad y precisión en el proceso contable.","actividad":"<span>Mantuvo actualizado el\\nsistema de información de registro, control y seguimiento de procesos\\njudiciales.<\\/span>"},{"obligacion":"4.        Brindar apoyo en la elaboración, consolidación y revisión de informes a remitir a los despachos judiciales en los cuales se evidencien las acciones desplegadas por los diferentes organismos del Distrito Especial, en el marco del cumplimiento de las sentencias de las acciones constitucionales en las que el Distrito Especial de Santiago de Cali sea parte o se encuentre vinculado.","actividad":"<p><span>Brindó apoyo en la consolidación y revisión de informes a remitir al\\ndespacho judicial en la Acción de Tutela con Radicado\\n76001-31-03-007-2024-00273-00<\\/span><\\/p>\\n\\n<p><span>.<\\/span><\\/p>"},{"obligacion":"5.        Asistir a las jornadas de socialización, mesas técnicas, mesas de estudio y comités de fortalecimiento a los que sea convocado.","actividad":"<p><span>Asistió a mesa de trabajo con el Departamento\\nAdministrativo de Gestión del Medio Ambiente para hacer comité de\\nseguimiento<span>&nbsp; <\\/span>la respuesta incidente\\ndesacato con Rad. 2024-00273<\\/span><\\/p>"},{"obligacion":"6.        Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual. \\nParágrafo. La representación judicial ejercida por el contratista corresponde a una actividad liberal que continúa ejerciendo este en cualquier escenario público o privado durante la ejecución del contrato sin exclusividad o subordinación alguna respecto al Distrito Especial de Santiago de Cali. No obstante, lo anterior, deberá dar cumplimento a las disposiciones consagradas en la Ley 1123 de 2007 (Código Disciplinario del Abogado) en lo que corresponde a deberes e incompatibilidades, especialmente la prohibición de litigio contra la entidad contratante.","actividad":"<p><span>No se\\nrequirió esta actividad para este periodo.<\\/span><\\/p>"}]', 'https://drive.google.com/drive/folders/1TL97XvSRL2StUalz5trlDgnbFqaqueXN?usp=sharing', '0520', '{"evidencia_3_0":{"name":"1. Correo de Alcaldía de Cali - MEMORIAL RESPUESTA INCIDENTE DE DESACATO PARA REVISION Y O.pdf","id":"1Zgde6gj5OFjPJIJ5OR1OLMmCNoTs8IAx","url":"https://drive.google.com/file/d/1Zgde6gj5OFjPJIJ5OR1OLMmCNoTs8IAx/view"},"evidencia_2_0":{"name":"Captura de Pantalla 2026-08-25 a la(s) 11.40.04 p.m..png","id":"1UtscICV_RNj1AgNONKWOg9Rixzv5PEfS","url":"https://drive.google.com/file/d/1UtscICV_RNj1AgNONKWOg9Rixzv5PEfS/view"},"evidencia_0_0":{"name":"Captura de Pantalla.png","id":"1ZPBr5_oBNaCKB2--DrSLyjdBqzi_iWl_","url":"https://drive.google.com/file/d/1ZPBr5_oBNaCKB2--DrSLyjdBqzi_iWl_/view"},"file_rut":{"name":"7. RUT - JHONI ORTEGA.pdf","id":"1d0Fc1-XfyKpQwASWT3UsJ73q4YEbOwdG","url":"https://drive.google.com/file/d/1d0Fc1-XfyKpQwASWT3UsJ73q4YEbOwdG/view"},"file_secop":{"name":"2. CONTRATO SECOP II - JHONI ORTEGA.pdf","id":"1fz6ulKzem4w-3mWtSmVdHP1iEfQ6Fl3J","url":"https://drive.google.com/file/d/1fz6ulKzem4w-3mWtSmVdHP1iEfQ6Fl3J/view"},"evidencia_4_0":{"name":"IMG_5569.jpg","id":"1IhhW7OmHgj9XSGxKK4Ig800ztegMJZEX","url":"https://drive.google.com/file/d/1IhhW7OmHgj9XSGxKK4Ig800ztegMJZEX/view"},"file_cedula":{"name":"6. CEDULA - JHONI ORTEGA.pdf","id":"18IoQnFUlMN7nVWGuomLr1rqbNEqdjjxO","url":"https://drive.google.com/file/d/18IoQnFUlMN7nVWGuomLr1rqbNEqdjjxO/view"},"file_seguridad_social":{"name":"8. SEGURIDAD SOCIAL CUOTA 1 - JHONI ORTEGA.pdf","id":"1nkPHiyLyjRaywW5riRSewrd3sfJrfBzK","url":"https://drive.google.com/file/d/1nkPHiyLyjRaywW5riRSewrd3sfJrfBzK/view"},"file_ficha_tecnica":{"name":"4. FICHA TECNICA - JHONI ORTEGA.pdf","id":"12u6wD4MfvmLFT_XpOG-TiLx-tKPlSIKP","url":"https://drive.google.com/file/d/12u6wD4MfvmLFT_XpOG-TiLx-tKPlSIKP/view"},"file_rpc":{"name":"1. RPC - JHONI ORTEGA.pdf","id":"1N15RTexO9CSCDRr42UZqFVvJhMM69G4x","url":"https://drive.google.com/file/d/1N15RTexO9CSCDRr42UZqFVvJhMM69G4x/view"}}', 'APROBADA PARA IMPRESION', 51, NULL, '', '', 2026, '', '', '', 'NO', 318, NULL, NULL);
