INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (278, 1942, '2026-08', 'PARCIAL', '2', '2026-07-07', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 4805000.00, 4805000.00, 19220000.00, '1083176160', '546052588', 'SIMPLE', '2026-08-06', '2026-07', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-15 00:39:13.484024', '2026-08-24', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar soporte en las actividades asignadas al gestor de compras del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\"><span>1.1.\\nRealizó apoyo en la elaboración, publicación y rendición del informe APUI\\ncorrespondiente al mes de julio de 2026, el cual fue presentado el día 19 de\\nagosto de 2026 a través de la plataforma DIARI (Dirección de Análisis de\\nInformación y Reacción Inmediata) de la Contraloría General de la República.\\nDicho informe consolida las novedades mensuales relacionadas con la\\ncontratación adelantada por el Departamento Administrativo de Gestión Jurídica\\nPública.<\\/span><\\/p><p style=\\"text-align: center;\\"><span><br><\\/span><\\/p><p style=\\"text-align: center;\\"><img src=\\"/combinacion/ImageServlet?id=1Qgeh