INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (285, 1959, '2026-10', 'PARCIAL', '4', '2026-07-08', '2026-12-30', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 3551000.00, 10653000.00, 7102000.00, '1085148274', '8823900477', 'simple', '2026-10-09', '2026-09', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-15 21:55:35.944403', '2026-10-26', 'N/A', 'N/A', 'N/A', 'N/A', E'[{"obligacion":"1. Brindar apoyo en la Subdirección de Defensa Judicial y Prevención del Daño Antijurídico en lo relacionado con la debida y oportuna notificación a los apoderados y organismos de la Administración Distrital, de las actuaciones prejudiciales, judiciales y administrativas en las que sea parte o tenga interés el Distrito Especial de Santiago de Cali, recibidas a través del buzón electrónico oficial de la entidad.","actividad":"<p><span style=\\"Arial\\" ,=\\"\\" sans-serif;=\\"\\">Notificó un total de 143 actuaciones\\nprejudiciales, judiciales y administrativas a los diferentes apoderados y\\norganismos de la administración Distrital a través del sistema de información\\nde registro, control y seguimiento de procesos.<\\/span><\\/p>"},{"obligacion":"2. Alimentar oportuna y permanentemente en el sistema de información de registro, control y seguimiento de procesos, todas las actuaciones judiciales y administrativas notificadas a través del buzón electrónico oficial de la Entidad.  Lo anterior, a efectos de conformar el expediente físico o virtual a que se refiere la Ley 2213 del 13 de junio de 2022, por parte del Apoderado Judicial.","actividad":"<p style=\\"text-align:justify\\"><span>Alimentó un total de 143 actuaciones prejudiciales,\\njudiciales y administrativas en el sistema de información de registro, control\\ny seguimiento de procesos.<\\/span><\\/p>"},{"obligacion":"3. Efectuar el registro diario en el archivo Excel compartido por DRIVE de las demandas admitidas y solicitudes de conciliación extrajudicial notificadas a través del buzón electrónico oficial de la Entidad, para continuar el proceso de creación y reparto. Así mismo, registrar las sentencias adversas, para ser notificadas al apoderado judicial y para ser incorporadas a la Agenda Semanal.","actividad":"<p style=\\"text-align:justify\\"><span>Registró un total de 123 traslados de las demandas admitidas\\ny solicitudes de conciliación extrajudiciales en la agenda Excel compartido por\\nDRIVE.<\\/span><\\/p>"},{"obligacion":"4. Brindar apoyo en la gestión de defensa judicial de los apoderados mediante el envío de los escritos, pruebas y demás piezas procesales ante las autoridades jurisdiccionales y administrativas competentes, a través del correo electrónico institucional destinado para tal fin.","actividad":"<p style=\\"text-align:justify\\"><span>Envió un total de 45 requerimientos e incidentes de desacato\\na las autoridades jurisdiccionales y administrativas competentes.&nbsp;<\\/span><\\/p>"},{"obligacion":"5. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.","actividad":"<p style=\\"text-align:justify\\"><span style=\\"Arial\\" ,=\\"\\" sans-serif;=\\"\\">No se presentaron otras actividades directamente relacionadas con el\\nobjeto contractual en este periodo.<\\/span><\\/p>"}]', 'https://drive.google.com/drive/folders/1pmg03PnrjJIwUQv3KrUZnk57_4mRCGC2?usp=sharing', '0739', '{"evidencia_3_0":{"name":"ilovepdf_merged.pdf","id":"1UkCN1-O6NFriBJ64hsq48sqIA_Kzt_vG","url":"https://drive.google.com/file/d/1UkCN1-O6NFriBJ64hsq48sqIA_Kzt_vG/view"},"evidencia_2_0":{"name":"Hoja de cálculo sin título.xlsx","id":"1hkGzYMPbeVNnyzQdBO2sGaJ9AXT5xZ2v","url":"https://drive.google.com/file/d/1hkGzYMPbeVNnyzQdBO2sGaJ9AXT5xZ2v/view"},"evidencia_0_0":{"name":"Reporte_Notificados_MAURICIO ANDRES CERON ORTEGA (1).xlsx","id":"1KqDHR6dooLatSBdc-tPXFlzgOckYcGYo","url":"https://drive.google.com/file/d/1KqDHR6dooLatSBdc-tPXFlzgOckYcGYo/view"},"file_paz_salvo_orfeo":{"name":"Paz y salvo orfeo Cuota No. 4.pdf","id":"1QQ-bMG7ZgwKJGQhz3S8HpHg2cps4q0D9","url":"https://drive.google.com/file/d/1QQ-bMG7ZgwKJGQhz3S8HpHg2cps4q0D9/view"},"evidencia_1_0":{"name":"PAZ Y SALVO DE CREACIONES MAURICIO ANDRES CERON ORTEGA (1).pdf","id":"1kCoFejlC8OQPXjYjnfyOwlJkcLQM-xVe","url":"https://drive.google.com/file/d/1kCoFejlC8OQPXjYjnfyOwlJkcLQM-xVe/view"},"file_paz_salvo_procesos":{"name":"Paz y salvo procesos Cuota No. 4.pdf","id":"1FRe-Yxht69ggS84VHrtf-9DXPprI-gGN","url":"https://drive.google.com/file/d/1FRe-Yxht69ggS84VHrtf-9DXPprI-gGN/view"},"file_seguridad_social":{"name":"4. SEGURIDAD SOCIAL CUOTA 4 - MAURICIO CERÓN.pdf","id":"1nkbpLHyYew3ClcHcOqwdos4tnuo9ytbZ","url":"https://drive.google.com/file/d/1nkbpLHyYew3ClcHcOqwdos4tnuo9ytbZ/view"},"file_paz_salvo_creaciones":{"name":"Paz y salvo creaciones Cuota No. 4.xlsx","id":"1Pr5V9onhGYzSOi71cY2xNwc8sIGYkmep","url":"https://drive.google.com/file/d/1Pr5V9onhGYzSOi71cY2xNwc8sIGYkmep/view"},"file_rpc":{"name":"1. RPC - MAURICIO CERÓN.pdf","id":"1uWhPjFWiJPeZsLX36Y61Q37PRhqMC9IJ","url":"https://drive.google.com/file/d/1uWhPjFWiJPeZsLX36Y61Q37PRhqMC9IJ/view"}}', 'APROBADA PARA IMPRESION', 12, NULL, '', '', 2026, '', '', '', 'NO', 321, NULL, NULL);
