INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (361, 1950, '2026-10', 'PARCIAL', '4', '2026-07-07', '2026-12-30', E'Modificación No. 001 del 20 de octubre de 2026 mediante la cual las partes acordaron: PRORROGAR el Contrato de Prestación de servicios profesionales No. 4121.010.26.1.098-2026 hasta el 30 de diciembre de 2026; y ADICIONAR el Contrato de Prestación de servicios profesionales No. 4121.010.26.1.098-2026 por la suma de ONCE MILLONES TRESCIENTOS VEINTISEIS MIL PESOS M/CTE ($11.326.000). Dicha adición se pagará en dos (2) cuotas iguales, cada una de ellas por valor de cinco millones seiscientos sesenta y tres mil pesos m/cte ($5.663.000).\r\n\r\nPor lo tanto, el valor total del contrato queda en la suma de TREINTA Y TRES MILLONES NOVECIENTOS SETENTA Y OCHO MIL PESOS M/CTE ($33.978.000).', 'N/A', 'N/A', 'N/A', 'N/A', 5663000.00, 16989000.00, 11326000.00, '95704263', '706222827', 'Mi planilla', '2026-10-02', '2026-10', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-22 10:37:56.938478', '2026-10-26', 'Mediante Modificación No. 001 del 20 de octubre de 2026 se adiciona la suma ONCE MILLONES TRESCIENTOS VEINTISEIS MIL PESOS M/CTE ($11.326.000).', 'Mediante Modificación No. 001 del 20 de octubre de 2026 se prorroga el Contrato de Prestación de servicios profesionales 4121.010.26.1.098-2026 hasta el 30 de diciembre de 2026.', 'N/A', 'N/A', E'[{"obligacion":"1.  Realizar soporte técnico a los equipos de cómputo, impresoras, equipos de digitalización y demás equipos del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el procedimiento de apoyar a\\nCarmen Estela Rosero revisando el equipo asignado a ella porque no prendía.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó la actividad\\nde revisar el equipo asignado a Angélica por que no prendía la pantalla.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de apoyar a la doctora Bernarda Sáenz revisando el equipo de\\ncómputo porque no ingresaba al internet.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de revisar el escáner asignado a María Fernanda Castaño.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de cambiar de tóner a la impresora ubicada en el despacho.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el procedimiento\\nde configurar la impresora del pasillo en el portátil de Alexandra Pechene Toro.<\\/span><\\/p>\\n\\n<span><div style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó\\nel procedimiento de configurar el tamaño de papel en la bandeja uno a la\\nimpresora ubicada en doctrina.<\\/span><\\/div><\\/span><p style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó la tarea de\\nconfigurar el escáner en el equipo asignado a Angie Jaramillo.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó el procedimiento de configurar\\nla impresora del pasillo en el portátil de Katherine Potes.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó la tarea de configurar\\nla impresora del pasillo al equipo asignado a Julián Sandoval.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó el\\nprocedimiento de solicitar vía mesa de servicio Mari el cambio de clave al\\nservidor con ip 192.168.20.94.<\\/span><\\/p><p style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó el procedimiento de vía mesa de servicio Mari solicitar la adición del permiso MODULO BCM al usuario en SAP de María Eugenia González.<\\/span><span><br><\\/span><\\/p>"},{"obligacion":"2. Brindar soporte técnico a los funcionarios del organismo en el manejo de los equipos y sistemas de información.","actividad":"<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Capacitó y asesoró a los usuarios\\ndel Departamento Administrativo de Gestión Jurídica en el Manejo y utilización\\nde Orfeo y las plantillas.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Brindó apoyo al grupo de\\ncontratación en la capacitación sobre las pruebas al nuevo sistema de\\ninformación contractual.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;&nbsp;<\\/span><\\/span><\\/span><span>Apoyó al Despacho en\\nél envió vía correo electrónico de la respuesta a los radicados Orfeo No. 202641210100036951,\\n202641210100039001, 202641210100038961, 202641730102506712 y 202641210100040621.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp; <\\/span><\\/span><\\/span><span>Brindó apoyo al\\ndoctor Armando Rojas en la radicación<\\/span><span> en el Orfeo de la contestación de una\\nacción de tutela luego fue enviada al correo de María Fernanda Rentería rad.\\n2026-00973.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp; <\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de apoyar al doctor Armando Rojas en la radicación en el Orfeo de\\nla contestación a una acción de tutela y luego fue envía al correo María\\nFernanda Rentería rad. 2026-01167.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp; <\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de solicitar vía mesa de servicio Mari la activación del usuario\\nen SAP de la doctora Ana Catalina Castro Lozano.<\\/span><\\/p>\\n\\n<span><div style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó el procedimiento de\\nsolicitar vía mesa de servicio Mari la activación del usuario en SAP de Oscar\\nMauricio Betancur Jiménez.<\\/span><\\/div><\\/span><p style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó el procedimiento de solicitar vía mesa de\\nservicio Mari la asignación de permiso de generar documentos en DARUMA al\\nusuario de Saira Ortiz.<\\/span><\\/p>"},{"obligacion":"3. Brindar apoyo técnico en la preparación de informes de acuerdo con las directrices impartidas por la Dirección del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\"><span><span>·&nbsp;<\\/span><\\/span><span>Elaboró y organizó\\ninforme en Excel sobre los temas y subtemas que han sido asignados a los\\nprocesos judiciales, y después fue enviados por correo electrónico para poder\\nelaborar el boletín estadístico. <\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Elaboró y organizó\\ninforme en Excel de todos los procesos tanto activos como terminados\\nregistrados en el Sistema de Información de procesos judiciales para ser\\nenviado por correo electrónico y elaborar el boletín estadístico.<\\/span><\\/p>\\n\\n<span><div style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Proyectó\\noficio sobre la información financiera con corte a 30 de septiembre del 2026.<\\/span><\\/div><\\/span>"},{"obligacion":"4. Brindar apoyo técnico para la administración, implementación, actualización, puesta en operación y capacitación de los Sistemas de Información que utilice el organismo.","actividad":"<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Brindó apoyo al grupo\\nde digitación del sistema de información de procesos judiciales en la\\ncorrección del número proceso que ha sido mal digitado tal como el 160268, 157911.<\\/span><\\/p>\\n\\n<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de apoyar a Elcy Gaviria, Beatriz Arenas y Juan José Casallas, Daniel\\nMartínez, Alexandra Pechene en la creación de despachos judiciales en el\\nSistema de Información de Procesos Judiciales tales como: Juzgado Cuarto Civil\\nMunicipal de Ejecución de Sentencias De Cali, Juzgado Once Penal Municipal con\\nFunciones de Conocimiento de Ibagué, Juzgado Primero Penal Municipal Para\\nAdolescentes Con Funciones de Control de Garantías del Circuito Judicial de\\nValledupar y el Juzgado 003 Penal Municipal de Cartago.<\\/span><\\/p>\\n\\n<span><div style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó\\nel procedimiento de crear un nuevo módulo para el seguimiento de generación de\\noficios de los incidentes.<\\/span><\\/div><\\/span>"},{"obligacion":"5. Realizar copias de seguridad a la base de datos de los sistemas de información que utilice el organismo, mantener una bitácora sobre los procesos de respaldo actualizado.","actividad":"<p>\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n<span>·&nbsp;<\\/span><span>Realizó el procedimiento de hacer backup a la base de\\ndatos del nuevo sistema de procesos judiciales y Sinfonia.<\\/span>\\n\\n\\n\\n<\\/p>"},{"obligacion":"6. Administrar y verificar el buen funcionamiento de los servidores del Departamento Administrativo de Gestión Jurídica Pública.","actividad":"<p style=\\"text-align: justify;\\">\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n<span>·&nbsp;<\\/span><span>Realizó la acción de utilizar el software MobaXterm\\npara<\\/span><span> <span>realizar la supervisión diaria del servidor de jurídica para que\\nGestión de procesos y <\\/span><\\/span><span>Sinfonía<span> estén siempre en\\nlínea y disponible.<\\/span><\\/span>\\n\\n\\n\\n<\\/p>"},{"obligacion":"7. Administrar la base de Datos de los sistemas información del Organismo.","actividad":"<p style=\\"text-align: justify;\\">\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n<span>·&nbsp;<\\/span><span>Realizó la actividad de utilizar el software MobaXterm\\npara poder hacer seguimiento al buen funcionamiento de la base de datos del\\nSistema de Procesos Judiciales y <\\/span><span>Sinfonía<span>.<\\/span><\\/span>\\n\\n\\n\\n<\\/p>"},{"obligacion":"8. Administrar y verificar el buen funcionamiento de la red de datos del Departamento Administrativo de Gestión Jurídico Público.","actividad":"<p>\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n<span>·&nbsp;<\\/span><span>Realizó el seguimiento al buen funcionamiento a la red\\nde datos del organismo.<\\/span>\\n\\n\\n\\n<\\/p>"},{"obligacion":"9. Administrar la Consola del Antivirus.","actividad":"<p style=\\"text-align: justify;\\">\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n<span>·&nbsp;<\\/span><span>Realizó el seguimiento al buen funcionamiento de la\\ninstalación del antivirus en los equipos del organismo.<\\/span>\\n\\n\\n\\n<\\/p>"},{"obligacion":"10. Reportar a DATIC información referente a los equipos tecnológicos cuando este lo requiera.","actividad":"<p style=\\"text-align: justify;\\"><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el\\nprocedimiento de reportar a DATIC mediante Google drive los equipos que\\nactualmente tiene en uso el organismo.<\\/span><\\/p>\\n\\n<span><div style=\\"text-align: justify;\\"><span>·&nbsp;<\\/span><span>Realizó\\nel procedimiento de reportar a DATIC mediante Mari los equipos que actualmente\\ntiene en uso el organismo<\\/span><\\/div><\\/span>"},{"obligacion":"11. Administrar el directorio activo (DA) de acuerdo con las instrucciones del DATIC y los requerimientos del organismo.","actividad":"<p><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el apoyo de resetear en el DA\\nla clave del usuario a Karen Escobar Zuleta.<\\/span><\\/p>\\n\\n<p><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó el apoyo de resetear en el DA\\nla clave del usuario de Manuel Velásquez.<\\/span><\\/p>\\n\\n<p><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span><span>Realizó el apoyo de resetear en el DA la clave del usuario de Patricia\\nFernández de Soto.<\\/span><\\/span><\\/p>\\n\\n<p><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span><span>Realizó el apoyo de resetear en el DA la clave del usuario de Héctor\\nMario Valencia.<\\/span><\\/span><\\/p>\\n\\n<p><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span><span>Realizó la tarea de crear en el DA el usuario a Javier Álvarez.<\\/span><\\/span><\\/p>\\n\\n<p><span><span>·<span>&nbsp;<\\/span><\\/span><\\/span><span>Realizó la tarea de crear en <\\/span><span>él DA<span>\\nel usuario a Jorge Enrique Villaquiran.<\\/span><\\/span><\\/p>\\n\\n<span>·&nbsp;<\\/span><span>Realizó\\nel apoyo de resetear en el DA la clave del usuario de María Eugenia González.<\\/span>"},{"obligacion":"12. Las demás actividades que le asigne el supervisor del contrato y que se encuentren directamente relacionadas con el objeto contractual.","actividad":"<p style=\\"text-align: justify;\\">\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n<span>·&nbsp;<\\/span><span>Realizó el procedimiento de continuar con el apoyo al\\nárea de contratación en el diseño de un sistema para la combinación automática\\nde documentos y se agregó un nuevo módulo para el registro de las cuentas.<\\/span>\\n\\n\\n\\n<\\/p>"}]', 'https://drive.google.com/drive/folders/1zRLQstdI-fmp3L4Cv4_yhUNGaLXzVyXJ?usp=sharing', '0731', '{"evidencia_1_0_6":{"name":"Envio de 202641210100038961.pdf","id":"17w1qQ9efZ4QBNo7N2hJIaHQwv9WsRjYb","url":"https://drive.google.com/file/d/17w1qQ9efZ4QBNo7N2hJIaHQwv9WsRjYb/view"},"evidencia_3_0":{"name":"Ajuste de radicados en Gestion de Procesos.pdf","id":"1NhJ_4oy1HJ6lvkSAsDoEShOCqLfhhCTr","url":"https://drive.google.com/file/d/1NhJ_4oy1HJ6lvkSAsDoEShOCqLfhhCTr/view"},"evidencia_1_0_7":{"name":"Envio de 202641210100040621.pdf","id":"1yGs405Dz2INDB98aaOwvyHaIotsgoFeK","url":"https://drive.google.com/file/d/1yGs405Dz2INDB98aaOwvyHaIotsgoFeK/view"},"evidencia_2_0":{"name":"Envio de informacion al estadistico 2.pdf","id":"1FF-HjDKKg38sNerYHxiOQQPvgzKS-kYN","url":"https://drive.google.com/file/d/1FF-HjDKKg38sNerYHxiOQQPvgzKS-kYN/view"},"evidencia_0_0":{"name":"Solicitud de cambio de clave servidor.pdf","id":"1UtKURm-zwyyZI1werCuGPMZu_sQfIDz8","url":"https://drive.google.com/file/d/1UtKURm-zwyyZI1werCuGPMZu_sQfIDz8/view"},"evidencia_1_0_8":{"name":"Solicitud de Activacion de usuario SAP Directora.pdf","id":"1ccI4I9B0xT_Sgn2fURzyVVuTgTNhi513","url":"https://drive.google.com/file/d/1ccI4I9B0xT_Sgn2fURzyVVuTgTNhi513/view"},"evidencia_1_0":{"name":"Activacion de usuario en SAP de Oscar Betancur.pdf","id":"1GGXWvlroSAq_ImpgRq__wgvJ6wUmb287","url":"https://drive.google.com/file/d/1GGXWvlroSAq_ImpgRq__wgvJ6wUmb287/view"},"evidencia_1_0_9":{"name":"Solicitud de Permiso Saira Ortiz Daruma.pdf","id":"1g5-XhlZvFCRpOILjVy9SYlZSJdiXNrKy","url":"https://drive.google.com/file/d/1g5-XhlZvFCRpOILjVy9SYlZSJdiXNrKy/view"},"evidencia_7_0":{"name":"Administracion de la red.pdf","id":"1-p5IAO3Zq6JTdc85mva9QJQ8edPAkelS","url":"https://drive.google.com/file/d/1-p5IAO3Zq6JTdc85mva9QJQ8edPAkelS/view"},"evidencia_6_0":{"name":"Administracion base de datos.pdf","id":"1FKlpxShOCkhCywJkSN3raCp1ypssDc85","url":"https://drive.google.c