INSERT INTO public.informes_supervision (id, contrato_id, periodo_informe, tipo_informe, numero_cuota, fecha_inicio_periodo, fecha_fin_periodo, modificaciones, suspensiones, reanudaciones, cesiones, terminacion_anticipada, valor_cuota_pagar, valor_acumulado_pagado, saldo_por_cancelar, planilla_numero, planilla_pin, planilla_operador, planilla_fecha_pago, planilla_periodo, observaciones_tecnicas, recomendaciones, fecha_creacion, fecha_suscripcion, adiciones, prorrogas, recibo_satisfaccion, constancia_paz_salvo, concepto_supervisor, url_drive_evidencias, consecutivo_cobro, soportes_json, estado_radicacion, id_revisor_asignado, observaciones_revision, observaciones_financieras, pago_seguridad_social, anio, eps, afp_pension, arl, es_contratista_nuevo, supervisor_id, estado_previo_devolucion, observaciones_contratista) VALUES (362, 1964, '2026-10', 'PARCIAL', '4', '2026-07-07', '2026-12-30', E'Modificación No. 001 del 20 de octubre de 2026 mediante la cual las partes acordaron: PRORROGAR el Contrato de Prestación de servicios profesionales No. 4121.010.26.1.112-2026 hasta el 30 de diciembre de 2026; y ADICIONAR el Contrato de Prestación de servicios profesionales No. 4121.010.26.1.112-2026 por la suma de QUINCE MILLONES SEISCIENTOS CINCUENTA Y DOS MIL PESOS M/CTE ($15.652.000). Dicha adición se pagará en dos (2) cuotas iguales, cada una de ellas por valor de siete millones ochocientos veintiséis mil pesos m/cte ($7.826.000).\r\n\r\nPor lo tanto, el valor total del contrato queda en la suma de CUARENTA Y SEIS MILLONES NOVECIENTOS CINCUENTA Y SEIS MIL PESOS M/CTE ($46.956.000).', 'N/A', 'N/A', 'N/A', 'N/A', 7826000.00, 23478000.00, 15652000.00, '9513134877 ', '762904881 ', 'APORTES EN LINEA', '2026-10-22', '2026-10', 'N/A', 'No se reportan recomendaciones para este periodo', '2026-10-22 11:02:53.091303', '2026-10-26', 'Mediante Modificación No. 001 del 20 de octubre de 2026 se adiciona la suma QUINCE MILLONES SEISCIENTOS CINCUENTA Y DOS MIL PESOS M/CTE ($15.652.000).', 'Mediante Modificación No. 001 del 20 de octubre de 2026 se prorroga el Contrato de Prestación de servicios profesionales 4121.010.26.1.112-2026 hasta el 30 de diciembre de 2026.', 'N/A', 'N/A', E'[{"obligacion":"1. Proyectar y revisar los actos administrativos tales como Decretos, Resoluciones, Circulares entre otros, a partir de la aplicación de las normas, jurisprudencia y doctrina; asignados por el Director de Gestión Jurídica y/o supervisor.","actividad":"<p><span>El contratista revisó desde el punto de vista jurídico los siguientes\\nactos administrativos:<\\/span><\\/p>\\n\\n<p><span><span>&nbsp;<\\/span><\\/span><\\/p>\\n\\n<p><span><span>1.<span>&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>Proyecto de <\\/span><span>Decreto \\u201cPOR EL CUAL SE LIQUIDAN LAS\\nMODIFICACIONES CONTENIDAS EN EL PRESUPUESTO GENERAL DEL DISTRITO DE SANTIAGO DE\\nCALI, PARA LA VIGENCIA 2026, APROBADAS MEDIANTE ACUERDO 0634 DEL 07 DE MAYO DE\\n2026\\u201d \\u2013 Solicitud adición presupuestal Secretaría de Educación por valor de\\n$1.456.535.313.<\\/span><span>\\n-<\\/span><span><span>&nbsp;<\\/span><\\/span><span>Trámite\\nrecibido mediante el Orfeo <\\/span><span>202641310200022564<\\/span><span>, proveniente de la Subdirección de Finanzas Públicas del\\nDepartamento Administrativo de <span>&nbsp;<\\/span>Hacienda y\\n<\\/span><span><span>&nbsp;<\\/span><\\/span><span><span>&nbsp;<\\/span><\\/span><span>cuya\\nrespuesta y trámite fue remitido para revisión <\\/span><span>del\\nDespacho de la Secretaría de Gobierno mediante Orfeo 202641210100073334. <\\/span><\\/p>\\n\\n<p><span><span>2.<span>&nbsp;&nbsp;&nbsp;&nbsp;\\n<\\/span><\\/span><\\/span><span>Proyecto de <\\/span><span>Decreto \\u201cPOR EL CUAL SE LIQUIDAN LAS\\nMODIFICACIONES CONTENIDAS EN EL PRESUPUESTO GENERAL DEL DISTRITO DE SANTIAGO DE\\nCALI, PARA LA VIGENCIA 2026, APROBADAS MEDIANTE ACUERDO 0634 DEL 07 DE MAYO DE\\n2026\\u201d \\u2013 Solicitud adición presupuestal Secretaría de Educación por valor d